import react from '@vitejs/plugin-react'
import tailwindcss from '@tailwindcss/vite'
import { defineConfig } from 'vite'

export default defineConfig({
  plugins: [react(), tailwindcss()],
  server: {
    host: true,
  },
})

@import 'tailwindcss';

@theme {
  --color-canvas: #f7f5ef;
  --color-surface: #ffffff;
  --color-sage: #9caf88;
  --color-forest: #344b35;
  --color-ink: #263328;
  --color-muted: #777e73;
  --color-line: #e3e5dc;
  --color-soft-sage: #e6ebdd;
  --color-alert: #e8412c;

  --font-sans: 'Manrope', ui-sans-serif, system-ui, -apple-system, sans-serif;

  --shadow-clay: 0 22px 50px -30px rgba(38, 51, 40, 0.42),
    inset 0 1px 0 rgba(255, 255, 255, 0.95);
  --shadow-soft: 0 10px 30px -20px rgba(38, 51, 40, 0.35);
  --shadow-float: 0 26px 70px -34px rgba(38, 51, 40, 0.5);

  --radius-card: 24px;
  --radius-section: 34px;
}

:root {
  font-family: var(--font-sans);
  color: #263328;
  background: #f7f5ef;
  font-synthesis: none;
  text-rendering: optimizeLegibility;
  -webkit-font-smoothing: antialiased;
}

* {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  margin: 0;
  min-width: 320px;
  min-height: 100vh;
  overflow-x: hidden;
  background:
    radial-gradient(circle at 8% -10%, rgba(156, 175, 136, 0.18), transparent 32rem),
    radial-gradient(circle at 96% 8%, rgba(230, 235, 221, 0.7), transparent 28rem),
    #f7f5ef;
}

button,
input,
select,
textarea {
  font: inherit;
}

button {
  cursor: pointer;
}

a {
  color: inherit;
  text-decoration: none;
}

::selection {
  background: rgba(156, 175, 136, 0.4);
  color: #263328;
}

:focus-visible {
  outline: 3px solid rgba(52, 75, 53, 0.55);
  outline-offset: 3px;
}

.clay-card {
  background: linear-gradient(145deg, #ffffff 0%, #fdfcf8 100%);
  border: 1px solid rgba(227, 229, 220, 0.95);
  border-radius: 24px;
  box-shadow:
    0 22px 50px -32px rgba(38, 51, 40, 0.42),
    inset 0 1px 0 rgba(255, 255, 255, 0.96);
}

.clay-card-hover {
  transition:
    transform 0.35s cubic-bezier(0.2, 0.8, 0.2, 1),
    box-shadow 0.35s cubic-bezier(0.2, 0.8, 0.2, 1),
    border-color 0.35s ease;
}

.clay-card-hover:hover {
  transform: translateY(-5px);
  border-color: rgba(156, 175, 136, 0.6);
  box-shadow:
    0 32px 60px -32px rgba(38, 51, 40, 0.42),
    inset 0 1px 0 rgba(255, 255, 255, 0.98);
}

.glass-panel {
  background: rgba(247, 245, 239, 0.74);
  backdrop-filter: blur(20px) saturate(150%);
  -webkit-backdrop-filter: blur(20px) saturate(150%);
  border: 1px solid rgba(255, 255, 255, 0.72);
  box-shadow:
    0 24px 60px -34px rgba(38, 51, 40, 0.45),
    inset 0 1px 0 rgba(255, 255, 255, 0.9);
}

.glass-dark {
  background: rgba(52, 75, 53, 0.86);
  backdrop-filter: blur(22px) saturate(140%);
  -webkit-backdrop-filter: blur(22px) saturate(140%);
  border: 1px solid rgba(255, 255, 255, 0.14);
}

.inset-field {
  background: rgba(230, 235, 221, 0.42);
  box-shadow: inset 0 2px 6px rgba(38, 51, 40, 0.08);
  border: 1px solid rgba(227, 229, 220, 0.9);
}

.soft-divider {
  border-color: rgba(227, 229, 220, 0.9);
}

.text-balance {
  text-wrap: balance;
}

.hide-scrollbar {
  scrollbar-width: none;
}

.hide-scrollbar::-webkit-scrollbar {
  display: none;
}

.scroll-thin {
  scrollbar-width: thin;
  scrollbar-color: rgba(156, 175, 136, 0.6) transparent;
}

.recharts-default-tooltip {
  border-radius: 16px !important;
  border: 1px solid rgba(227, 229, 220, 0.9) !important;
  box-shadow: 0 18px 40px -24px rgba(38, 51, 40, 0.4) !important;
}

@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }

  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

export const delay = (ms: number) => new Promise<void>((resolve) => setTimeout(resolve, ms))

export const formatINR = (value: number) =>
  new Intl.NumberFormat('en-IN', {
    style: 'currency',
    currency: 'INR',
    maximumFractionDigits: 0,
  }).format(value)

export const formatNumber = (value: number) => new Intl.NumberFormat('en-IN').format(value)

export const formatDate = (value: string, options?: Intl.DateTimeFormatOptions) =>
  new Intl.DateTimeFormat('en-IN', {
    day: '2-digit',
    month: 'short',
    year: 'numeric',
    ...options,
  }).format(new Date(value))

export const formatDateTime = (value: string) =>
  formatDate(value, { hour: '2-digit', minute: '2-digit' })

export const relativeTime = (value: string) => {
  const diff = Date.now() - new Date(value).getTime()
  const minutes = Math.round(diff / 60000)
  if (minutes < 1) return 'just now'
  if (minutes < 60) return `${minutes}m ago`
  const hours = Math.round(minutes / 60)
  if (hours < 24) return `${hours}h ago`
  const days = Math.round(hours / 24)
  if (days < 30) return `${days}d ago`
  return formatDate(value)
}

export const makeId = (prefix: string) =>
  `${prefix}-${Date.now().toString(36).toUpperCase()}-${Math.random().toString(36).slice(2, 6).toUpperCase()}`

export const clamp = (value: number, min: number, max: number) => Math.min(Math.max(value, min), max)

import { DEMO_ADMINS } from '../data/users'
import { DEMO_EXPERTS } from '../data/experts'
import { DEMO_FARMERS } from '../data/farmers'
import type { DemoUser, Role } from '../types'
import { delay } from './utils'

export interface LoginInput {
  email: string
  password: string
  role: Role
}

export interface RegisterInput extends LoginInput {
  name: string
  location: string
}

/**
 * Demo-only authentication boundary.
 * Replace this module with Amazon Cognito calls in a future phase;
 * UI components must continue to consume the same DemoUser shape.
 */
export const authService = {
  async login(input: LoginInput): Promise<DemoUser> {
    await delay(650)
    if (!input.email.trim() || !input.password.trim()) {
      throw new Error('Enter a demo email and password to continue.')
    }

    const pool =
      input.role === 'farmer' ? DEMO_FARMERS : input.role === 'expert' ? DEMO_EXPERTS : DEMO_ADMINS
    const matched = pool.find((user) => user.email.toLowerCase() === input.email.trim().toLowerCase())
    return (
      matched ?? {
        ...pool[0],
        email: input.email.trim(),
        name: input.email.split('@')[0].replace(/[._-]/g, ' ').replace(/\b\w/g, (char) => char.toUpperCase()),
      }
    )
  },

  async quickLogin(role: Role): Promise<DemoUser> {
    await delay(450)
    if (role === 'farmer') return DEMO_FARMERS[0]
    if (role === 'expert') return DEMO_EXPERTS[0]
    return DEMO_ADMINS[0]
  },

  async register(input: RegisterInput): Promise<DemoUser> {
    await delay(750)
    if (!input.name.trim() || !input.email.trim() || !input.password.trim()) {
      throw new Error('Name, email and password are required.')
    }
    return {
      id: `new-${input.role}-${Date.now()}`,
      name: input.name.trim(),
      email: input.email.trim(),
      role: input.role,
      location: input.location || 'Location not set',
      phone: 'Not provided',
      status: 'active',
      joinedAt: new Date().toISOString().slice(0, 10),
      avatar: input.name
        .split(' ')
        .map((part) => part[0])
        .join('')
        .slice(0, 2)
        .toUpperCase(),
    }
  },

  async requestPasswordReset(email: string): Promise<void> {
    await delay(600)
    if (!email.includes('@')) throw new Error('Enter a valid email address.')
  },

  async resetPassword(password: string, confirmPassword: string): Promise<void> {
    await delay(600)
    if (password.length < 8) throw new Error('Use at least 8 characters.')
    if (password !== confirmPassword) throw new Error('Passwords do not match.')
  },
}

import { DEMO_PRICE_TREND } from '../data/mandiPrices'
import type { MandiPrice } from '../types'
import { formatINR } from './utils'

export interface MandiFilters {
  crop: string
  state: string
  district: string
  query: string
}

export const mandiService = {
  filter(prices: MandiPrice[], filters: MandiFilters): MandiPrice[] {
    return prices.filter((row) => {
      const matchesCrop = filters.crop === 'All crops' || row.crop === filters.crop
      const matchesState = filters.state === 'All states' || row.state === filters.state
      const matchesDistrict = filters.district === 'All districts' || row.district === filters.district
      const query = filters.query.trim().toLowerCase()
      const matchesQuery =
        !query ||
        [row.crop, row.mandi, row.district, row.state].some((value) => value.toLowerCase().includes(query))
      return matchesCrop && matchesState && matchesDistrict && matchesQuery
    })
  },

  summary(rows: MandiPrice[]) {
    if (rows.length === 0) {
      return { min: 0, max: 0, modal: 0, average: 0, mandiCount: 0 }
    }
    const min = Math.min(...rows.map((row) => row.minPrice))
    const max = Math.max(...rows.map((row) => row.maxPrice))
    const modal = Math.round(rows.reduce((sum, row) => sum + row.modalPrice, 0) / rows.length)
    return { min, max, modal, average: modal, mandiCount: rows.length }
  },

  trend(crop: string) {
    const offset = crop === 'Tomato' ? 0 : crop === 'Wheat' ? 480 : crop === 'Onion' ? -320 : 120
    return DEMO_PRICE_TREND.map((point) => ({ ...point, price: Math.max(400, point.price + offset) }))
  },

  estimate(quantityQtl: number, pricePerQtl: number, transportCost: number) {
    const gross = quantityQtl * pricePerQtl
    const net = Math.max(0, gross - transportCost)
    return { gross, net, transportCost, formattedNet: formatINR(net) }
  },
}

import type { IrrigationInput, IrrigationRecommendation } from '../types'

const cropNeed: Record<string, number> = {
  Tomato: 1.05,
  Wheat: 0.9,
  Grapes: 0.72,
  Onion: 0.68,
  Rice: 1.35,
  Cotton: 0.95,
  Maize: 0.92,
  Potato: 0.86,
}

const stageFactor: Record<string, number> = {
  Seedling: 0.65,
  Vegetative: 0.9,
  Flowering: 1.15,
  'Fruit / grain formation': 1.2,
  Maturity: 0.55,
}

export const irrigationService = {
  recommend(input: IrrigationInput): IrrigationRecommendation {
    const hot = input.temperature >= 32
    const dryWeather = ['Hot & dry', 'Sunny', 'Partly cloudy'].includes(input.weather)
    const rainExpected = input.weather.toLowerCase().includes('rain')
    const moisture = Math.min(100, Math.max(0, input.moisture))
    const sandy = input.soilType.toLowerCase().includes('sandy')
    const need = (cropNeed[input.crop] ?? 0.9) * (stageFactor[input.stage] ?? 1)
    const threshold = sandy ? 40 : 34

    let action: IrrigationRecommendation['action'] = 'hold'
    if (moisture < threshold - 8 || (hot && dryWeather && moisture < threshold)) action = 'irrigate-now'
    else if (moisture < threshold + 8 && !rainExpected) action = 'schedule'

    const baseLitres = Math.round(4200 * need * (action === 'irrigate-now' ? 1 : action === 'schedule' ? 0.7 : 0.25))
    const waterLitres = Math.max(900, baseLitres)
    const durationMin = Math.round(waterLitres / 145)

    const reasoning = [
      `Simulated soil moisture is ${moisture}%. ${sandy ? 'Sandy soils drain faster, so the demo threshold is higher.' : 'The default demo threshold is 34% for this soil group.'}`,
      `${input.crop} at ${input.stage.toLowerCase()} stage has a relative water need of ${need.toFixed(2)}× in this demo model.`,
      rainExpected
        ? 'Rain is expected in the simulated weather context, so irrigation can be deferred.'
        : hot
          ? 'High simulated temperature increases evapotranspiration.'
          : 'Weather context does not indicate immediate rainfall.',
      `Soil type: ${input.soilType}.`,
    ]

    return {
      headline:
        action === 'irrigate-now'
          ? 'Irrigation suggested soon'
          : action === 'schedule'
            ? 'Schedule a lighter irrigation'
            : 'Hold irrigation for now',
      action,
      waterLitres,
      durationMin,
      bestWindow: action === 'hold' ? 'Reassess in 24 hours' : 'Early morning or late evening',
      reasoning,
      confidenceNote:
        'Demo recommendation derived only from the values you entered. Simulated sensor readings are not field measurements.',
    }
  },
}

import type { StorageStatus } from '../types'

export interface StorageThresholds {
  minTemp: number
  maxTemp: number
  maxHumidity: number
}

export const storageService = {
  evaluate(tempC: number, humidity: number, thresholds: StorageThresholds): StorageStatus {
    const tempBreach = tempC < thresholds.minTemp || tempC > thresholds.maxTemp
    const humidityBreach = humidity > thresholds.maxHumidity
    if (tempBreach && humidityBreach) return 'critical'
    if (tempBreach || humidityBreach) {
      const tempGap = Math.max(thresholds.minTemp - tempC, tempC - thresholds.maxTemp, 0)
      const humidityGap = Math.max(humidity - thresholds.maxHumidity, 0)
      return tempGap > 3 || humidityGap > 6 ? 'critical' : 'warning'
    }
    return 'normal'
  },

  statusMessage(status: StorageStatus) {
    if (status === 'critical') return 'Above demo safety threshold — inspect promptly'
    if (status === 'warning') return 'Approaching demo threshold — monitor closely'
    return 'Within configured demo thresholds'
  },

  summary(batches: { status: StorageStatus; quantityKg: number }[]) {
    return {
      total: batches.length,
      normal: batches.filter((batch) => batch.status === 'normal').length,
      warning: batches.filter((batch) => batch.status === 'warning').length,
      critical: batches.filter((batch) => batch.status === 'critical').length,
      quantity: batches.reduce((sum, batch) => sum + batch.quantityKg, 0),
    }
  },
}

import type { Scheme } from '../types'

export interface SchemeFilters {
  query: string
  category: string
  state: string
}

export const schemeService = {
  filter(schemes: Scheme[], filters: SchemeFilters): Scheme[] {
    const query = filters.query.trim().toLowerCase()
    return schemes.filter((scheme) => {
      const matchesCategory = filters.category === 'All categories' || scheme.category === filters.category
      const matchesState = filters.state === 'All states' || scheme.state === filters.state || scheme.state === 'All India'
      const matchesQuery =
        !query ||
        [scheme.name, scheme.summary, scheme.category, ...scheme.tags].some((value) =>
          value.toLowerCase().includes(query),
        )
      return matchesCategory && matchesState && matchesQuery
    })
  },

  applicationStages: ['Details review', 'Documents checklist', 'Application preparation', 'Submitted (demo)'],

  nextStage(progress: number) {
    const stages = this.applicationStages
    const index = Math.min(stages.length - 1, Math.floor(progress / 25))
    const nextProgress = Math.min(100, progress + 25)
    return {
      progress: nextProgress,
      stage: stages[Math.min(stages.length - 1, Math.floor(nextProgress / 25))],
      complete: nextProgress >= 100,
    }
  },
}

import { createContext, useCallback, useContext, useMemo, useState } from 'react'
