const AppContext = createContext<AppContextValue | null>(null)

export function AppProvider({ children }: { children: ReactNode }) {
  const [state, setState] = useState<AppState>(initialState)

  const addAuditLog = useCallback((actor: string, role: Role, action: string, target: string) => {
    setState((current) => ({
      ...current,
      auditLogs: [
        {
          id: makeId('LOG'),
          actor,
          role,
          action,
          target,
          timestamp: new Date().toISOString(),
        },
        ...current.auditLogs,
      ],
    }))
  }, [])

  const value = useMemo<AppContextValue>(
    () => ({
      ...state,
      addCase: (cropCase) =>
        setState((current) => ({ ...current, cases: [cropCase, ...current.cases] })),
      reviewCase: (id, notes, guidance, status, reviewer) =>
        setState((current) => ({
          ...current,
          cases: current.cases.map((item) =>
            item.id === id
              ? {
                  ...item,
                  reviewStatus: status,
                  status: status === 'completed' ? 'resolved' : 'expert_review',
                  expertNotes: notes,
                  expertGuidance: guidance,
                  reviewedAt: new Date().toISOString(),
                  reviewedBy: reviewer,
                }
              : item,
          ),
        })),
      saveScheme: (schemeId) =>
        setState((current) =>
          current.savedSchemeIds.includes(schemeId)
            ? current
            : { ...current, savedSchemeIds: [...current.savedSchemeIds, schemeId] },
        ),
      unsaveScheme: (schemeId) =>
        setState((current) => ({
          ...current,
          savedSchemeIds: current.savedSchemeIds.filter((id) => id !== schemeId),
        })),
      startApplication: (schemeId, farmerId) =>
        setState((current) =>
          current.applications.some((app) => app.schemeId === schemeId && app.farmerId === farmerId)
            ? current
            : {
                ...current,
                applications: [
                  {
                    id: makeId('APP'),
                    schemeId,
                    farmerId,
                    progress: 25,
                    stage: 'Documents checklist',
                    updatedAt: new Date().toISOString(),
                  },
                  ...current.applications,
                ],
              },
        ),
      advanceApplication: (applicationId) =>
        setState((current) => ({
          ...current,
          applications: current.applications.map((app) => {
            if (app.id !== applicationId || app.progress >= 100) return app
            const progress = Math.min(100, app.progress + 25)
            const stage =
              progress >= 100
                ? 'Submitted (demo)'
                : progress >= 75
                  ? 'Application preparation'
                  : progress >= 50
                    ? 'Documents checklist'
                    : 'Details review'
            return { ...app, progress, stage, updatedAt: new Date().toISOString() }
          }),
        })),
      notify: ({ title, body, severity, audience }) =>
        setState((current) => ({
          ...current,
          notifications: [
            {
              id: makeId('NOTIF'),
              title,
              body,
              severity,
              audience,
              createdAt: new Date().toISOString(),
              read: false,
            },
            ...current.notifications,
          ],
        })),
      markNotificationRead: (id) =>
        setState((current) => ({
          ...current,
          notifications: current.notifications.map((item) =>
            item.id === id ? { ...item, read: true } : item,
          ),
        })),
      markAllNotificationsRead: (audience) =>
        setState((current) => ({
          ...current,
          notifications: current.notifications.map((item) =>
            item.audience === audience || item.audience === 'all' ? { ...item, read: true } : item,
          ),
        })),
      addStorageBatch: (batch) =>
        setState((current) => ({ ...current, storageBatches: [batch, ...current.storageBatches] })),
      addInspection: (batchId, notes, inspector) =>
        setState((current) => ({
          ...current,
          storageBatches: current.storageBatches.map((batch) =>
            batch.id === batchId
              ? {
                  ...batch,
                  inspections: [
                    {
                      id: makeId('INSP'),
                      date: new Date().toISOString(),
                      inspector,
                      notes,
                      condition: batch.status,
                    },
                    ...batch.inspections,
                  ],
                }
              : batch,
          ),
        })),
      addMandiAlert: (alert) =>
        setState((current) => ({
          ...current,
          mandiAlerts: [
            { ...alert, id: makeId('ALERT'), createdAt: new Date().toISOString() },
            ...current.mandiAlerts,
          ],
        })),
      removeMandiAlert: (id) =>
        setState((current) => ({
          ...current,
          mandiAlerts: current.mandiAlerts.filter((alert) => alert.id !== id),
        })),
      toggleReminder: (id) =>
        setState((current) => ({
          ...current,
          irrigationSchedules: current.irrigationSchedules.map((item) =>
            item.id === id ? { ...item, reminder: !item.reminder } : item,
          ),
        })),
      updateUserStatus: (id, status) =>
        setState((current) => ({
          ...current,
          users: current.users.map((user) => (user.id === id ? { ...user, status } : user)),
        })),
      addUser: (user) => setState((current) => ({ ...current, users: [user, ...current.users] })),
      addAuditLog,
      updateSettings: (patch) =>
        setState((current) => ({ ...current, settings: { ...current.settings, ...patch } })),
    }),
    [state, addAuditLog],
  )

  return <AppContext.Provider value={value}>{children}</AppContext.Provider>
}

export function useApp() {
  const context = useContext(AppContext)
  if (!context) throw new Error('useApp must be used inside AppProvider')
  return context
}

import { createContext, useCallback, useContext, useMemo, useState } from 'react'
import type { ReactNode } from 'react'
import { authService } from '../services/authService'
import type { LoginInput, RegisterInput } from '../services/authService'
import { useApp } from '../services/store'
import type { DemoUser, Role } from '../types'

const STORAGE_KEY = 'krishi360-demo-user'

interface AuthContextValue {
  user: DemoUser | null
  loading: boolean
  login: (input: LoginInput) => Promise<DemoUser>
  quickLogin: (role: Role) => Promise<DemoUser>
  register: (input: RegisterInput) => Promise<DemoUser>
  logout: () => void
  updateProfile: (patch: Partial<DemoUser>) => void
}

const AuthContext = createContext<AuthContextValue | null>(null)

function readStoredUser(): DemoUser | null {
  try {
    const raw = sessionStorage.getItem(STORAGE_KEY)
    return raw ? (JSON.parse(raw) as DemoUser) : null
  } catch {
    return null
  }
}

export function AuthProvider({ children }: { children: ReactNode }) {
  const [user, setUser] = useState<DemoUser | null>(readStoredUser)
  const [loading, setLoading] = useState(false)
  const { addAuditLog, addUser } = useApp()

  const persist = useCallback((next: DemoUser | null) => {
    setUser(next)
    if (next) sessionStorage.setItem(STORAGE_KEY, JSON.stringify(next))
    else sessionStorage.removeItem(STORAGE_KEY)
  }, [])

  const login = useCallback(
    async (input: LoginInput) => {
      setLoading(true)
      try {
        const next = await authService.login(input)
        persist(next)
        addAuditLog(next.name, next.role, 'Signed in to demo portal', 'Authentication')
        return next
      } finally {
        setLoading(false)
      }
    },
    [addAuditLog, persist],
  )

  const quickLogin = useCallback(
    async (role: Role) => {
      setLoading(true)
      try {
        const next = await authService.quickLogin(role)
        persist(next)
        addAuditLog(next.name, next.role, 'Switched demo role', 'Authentication')
        return next
      } finally {
        setLoading(false)
      }
    },
    [addAuditLog, persist],
  )

  const register = useCallback(
    async (input: RegisterInput) => {
      setLoading(true)
      try {
        const next = await authService.register(input)
        addUser(next)
        persist(next)
        addAuditLog(next.name, next.role, 'Created demo account', 'Authentication')
        return next
      } finally {
        setLoading(false)
      }
    },
    [addAuditLog, addUser, persist],
  )

  const logout = useCallback(() => {
    if (user) addAuditLog(user.name, user.role, 'Signed out of demo portal', 'Authentication')
    persist(null)
  }, [addAuditLog, persist, user])

  const updateProfile = useCallback(
    (patch: Partial<DemoUser>) => {
      setUser((current) => {
        if (!current) return current
        const next = { ...current, ...patch }
        sessionStorage.setItem(STORAGE_KEY, JSON.stringify(next))
        return next
      })
    },
    [],
  )

  const value = useMemo<AuthContextValue>(
    () => ({ user, loading, login, quickLogin, register, logout, updateProfile }),
    [user, loading, login, quickLogin, register, logout, updateProfile],
  )

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>
}

export function useAuth() {
  const context = useContext(AuthContext)
  if (!context) throw new Error('useAuth must be used inside AuthProvider')
  return context
}

import { createContext, useCallback, useContext, useMemo, useState } from 'react'
import type { ReactNode } from 'react'
import type { Severity } from '../types'

export interface ToastMessage {
  id: string
  title: string
  description?: string
  severity: Severity
}

interface ToastContextValue {
  toasts: ToastMessage[]
  show: (title: string, description?: string, severity?: Severity) => void
  dismiss: (id: string) => void
}

const ToastContext = createContext<ToastContextValue | null>(null)

export function ToastProvider({ children }: { children: ReactNode }) {
  const [toasts, setToasts] = useState<ToastMessage[]>([])

  const dismiss = useCallback((id: string) => {
    setToasts((current) => current.filter((toast) => toast.id !== id))
  }, [])

  const show = useCallback(
    (title: string, description?: string, severity: Severity = 'success') => {
      const id = `${Date.now()}-${Math.random().toString(36).slice(2)}`
      setToasts((current) => [...current, { id, title, description, severity }])
      window.setTimeout(() => dismiss(id), 4200)
    },
    [dismiss],
  )

  const value = useMemo<ToastContextValue>(() => ({ toasts, show, dismiss }), [toasts, show, dismiss])

  return <ToastContext.Provider value={value}>{children}</ToastContext.Provider>
}

export function useToast() {
  const context = useContext(ToastContext)
  if (!context) throw new Error('useToast must be used inside ToastProvider')
  return context
}

import type { ButtonHTMLAttributes, ReactNode } from 'react'

export type ButtonVariant = 'primary' | 'secondary' | 'outline' | 'ghost' | 'danger'
export type ButtonSize = 'sm' | 'md' | 'lg'

const base =
  'inline-flex items-center justify-center gap-2 rounded-2xl font-semibold tracking-[-0.01em] transition-all duration-300 active:scale-[0.98] disabled:pointer-events-none disabled:opacity-50 focus-visible:outline-3 focus-visible:outline-offset-2'

const variants: Record<ButtonVariant, string> = {
  primary:
    'bg-forest text-white shadow-[0_14px_28px_-14px_rgba(52,75,53,0.85)] hover:bg-[#2b402c] hover:shadow-[0_18px_34px_-14px_rgba(52,75,53,0.85)]',
  secondary: 'bg-soft-sage text-forest hover:bg-sage/45 hover:text-[#263b27]',
  outline: 'border border-line bg-white/70 text-ink hover:border-sage hover:bg-white',
  ghost: 'text-forest hover:bg-soft-sage/70',
  danger: 'bg-alert text-white shadow-[0_12px_26px_-14px_rgba(232,65,44,0.9)] hover:bg-[#cf3523]',
}

const sizes: Record<ButtonSize, string> = {
  sm: 'min-h-9 px-3.5 py-2 text-xs',
  md: 'min-h-11 px-5 py-2.5 text-sm',
  lg: 'min-h-13 px-7 py-3 text-sm sm:text-base',
}

export function buttonClasses(
  variant: ButtonVariant = 'primary',
  size: ButtonSize = 'md',
  className = '',
) {
  return `${base} ${variants[variant]} ${sizes[size]} ${className}`
}

interface ButtonProps extends ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: ButtonVariant
  size?: ButtonSize
  children: ReactNode
}

export function Button({ variant = 'primary', size = 'md', className = '', children, ...props }: ButtonProps) {
  return (
    <button className={buttonClasses(variant, size, className)} {...props}>
      {children}
    </button>
  )
}

