import { useState } from 'react'
import { AnimatePresence, motion } from 'framer-motion'
import { Check, ChevronDown, UserRoundCog } from 'lucide-react'
import { useNavigate } from 'react-router-dom'
import { useAuth } from '../../context/AuthContext'
import { useToast } from '../../context/ToastContext'
import type { Role } from '../../types'

const roles: { id: Role; label: string; description: string }[] = [
  { id: 'farmer', label: 'Farmer Portal', description: 'Farm, crops and field modules' },
  { id: 'expert', label: 'Expert Portal', description: 'Case review and advisory' },
  { id: 'admin', label: 'Admin Portal', description: 'Platform operations' },
]

const homeFor: Record<Role, string> = {
  farmer: '/farmer/dashboard',
  expert: '/expert/dashboard',
  admin: '/admin/dashboard',
}

export function RoleSwitcher() {
  const [open, setOpen] = useState(false)
  const { user, quickLogin, loading } = useAuth()
  const { show } = useToast()
  const navigate = useNavigate()

  const switchTo = async (role: Role) => {
    setOpen(false)
    if (user?.role === role) {
      navigate(homeFor[role])
      return
    }
    try {
      const next = await quickLogin(role)
      show(`Switched to ${next.role} demo`, `Continuing as ${next.name}.`, 'success')
      navigate(homeFor[role])
    } catch {
      show('Could not switch role', 'Please try again.', 'critical')
    }
  }

  return (
    <div className="relative">
      <button
        type="button"
        onClick={() => setOpen((value) => !value)}
        aria-expanded={open}
        aria-haspopup="menu"
        className="flex items-center gap-2 rounded-2xl border border-line bg-white/70 px-3 py-2 text-xs font-bold text-forest transition-colors hover:border-sage hover:bg-white"
      >
        <UserRoundCog size={15} />
        <span className="hidden sm:inline">Demo role</span>
        <span className="sm:hidden">Role</span>
        <ChevronDown size={14} className={`transition-transform ${open ? 'rotate-180' : ''}`} />
      </button>
      <AnimatePresence>
        {open ? (
          <motion.div
            role="menu"
            initial={{ opacity: 0, y: 8, scale: 0.98 }}
            animate={{ opacity: 1, y: 0, scale: 1 }}
            exit={{ opacity: 0, y: 6, scale: 0.98 }}
            transition={{ duration: 0.18 }}
            className="glass-panel absolute right-0 z-50 mt-2 w-64 rounded-2xl p-2"
          >
            {roles.map((role) => (
              <button
                key={role.id}
                type="button"
                role="menuitem"
                disabled={loading}
                onClick={() => void switchTo(role.id)}
                className={`flex w-full items-center gap-3 rounded-xl px-3 py-2.5 text-left transition-colors hover:bg-white ${user?.role === role.id ? 'bg-soft-sage/70' : ''}`}
              >
                <span className={`flex size-8 items-center justify-center rounded-xl ${user?.role === role.id ? 'bg-forest text-white' : 'bg-soft-sage text-forest'}`}>
                  {user?.role === role.id ? <Check size={15} /> : <UserRoundCog size={15} />}
                </span>
                <span className="min-w-0">
                  <span className="block text-xs font-bold text-ink">{role.label}</span>
                  <span className="block text-[10px] text-muted">{role.description}</span>
                </span>
              </button>
            ))}
          </motion.div>
        ) : null}
      </AnimatePresence>
    </div>
  )
}

