          <nav className="scroll-thin flex-1 space-y-5 overflow-y-auto pb-4" aria-label={`${portalName} navigation`}>
            {groups.map((group) => (
              <div key={group.name}>
                <p className="mb-2 px-3 text-[10px] font-extrabold tracking-[0.14em] text-muted uppercase">{group.name}</p>
                <div className="space-y-1">
                  {group.items.map((item) => {
                    const Icon = item.icon
                    const active = current.to === item.to
                    return (
                      <NavLink
                        key={item.to}
                        to={item.to}
                        className={`relative flex items-center gap-3 rounded-2xl px-3 py-2.5 text-[13px] font-semibold transition-colors ${
                          active ? 'text-forest' : 'text-muted hover:bg-white/60 hover:text-ink'
                        }`}
