import type { ReactNode } from 'react'
import { Navigate } from 'react-router-dom'
import { useAuth } from '../context/AuthContext'
import type { Role } from '../types'

const homeFor: Record<Role, string> = {
  farmer: '/farmer/dashboard',
  expert: '/expert/dashboard',
  admin: '/admin/dashboard',
}

export function ProtectedRoute({ children, allowedRole }: { children: ReactNode; allowedRole: Role }) {
  const { user } = useAuth()

  if (!user) return <Navigate to="/login" replace />
  if (user.role !== allowedRole) return <Navigate to={homeFor[user.role]} replace />
  return <>{children}</>
}

import { useState } from 'react'
import type { FormEvent } from 'react'
import { ArrowRight, LockKeyhole, Mail, Sparkles } from 'lucide-react'
import { Link, useNavigate, useSearchParams } from 'react-router-dom'
import { useAuth } from '../../context/AuthContext'
import { useToast } from '../../context/ToastContext'
import { Button, buttonClasses } from '../../components/ui/Button'
import { Field, Input } from '../../components/ui/Input'
import type { Role } from '../../types'
import { AuthShell } from './AuthShell'

const roleOptions: { id: Role; label: string }[] = [
  { id: 'farmer', label: 'Farmer' },
  { id: 'expert', label: 'Expert' },
  { id: 'admin', label: 'Admin' },
]

const homeFor: Record<Role, string> = {
  farmer: '/farmer/dashboard',
  expert: '/expert/dashboard',
  admin: '/admin/dashboard',
}

export function LoginPage() {
  const [params] = useSearchParams()
  const initialRole = params.get('role')
  const [role, setRole] = useState<Role>(
    initialRole === 'farmer' || initialRole === 'expert' || initialRole === 'admin' ? initialRole : 'farmer',
  )
  const [email, setEmail] = useState('')
  const [password, setPassword] = useState('')
  const [error, setError] = useState('')
  const { login, quickLogin, loading } = useAuth()
  const { show } = useToast()
  const navigate = useNavigate()

  const submit = async (event: FormEvent) => {
    event.preventDefault()
    setError('')
    try {
      const user = await login({ email, password, role })
      show(`Welcome, ${user.name.split(' ')[0]}`, 'Demo sign-in successful.', 'success')
      navigate(homeFor[user.role])
    } catch (cause) {
      setError(cause instanceof Error ? cause.message : 'Could not sign in.')
    }
  }

  const quick = async (selected: Role) => {
    setError('')
    try {
      const user = await quickLogin(selected)
      show(`Entering ${selected} portal`, `Signed in as ${user.name}.`, 'success')
      navigate(homeFor[user.role])
    } catch {
      setError('Could not start the demo. Please try again.')
    }
  }

  return (
    <AuthShell
      eyebrow="Welcome back"
      title="Sign in to your workspace"
      description="Use any email and password with a role, or enter instantly with a one-click demo profile."
      footer={
        <>
          New to KRISHI360 AI?{' '}
          <Link to="/register" className="font-extrabold text-forest hover:underline">Create a demo account</Link>
        </>
      }
    >
      <div className="grid grid-cols-3 gap-2 rounded-2xl inset-field p-1.5">
        {roleOptions.map((option) => (
          <button
            key={option.id}
            type="button"
            onClick={() => setRole(option.id)}
            className={`rounded-xl px-3 py-2.5 text-xs font-extrabold transition-all ${
              role === option.id ? 'bg-forest text-white shadow-[0_8px_18px_-12px_rgba(52,75,53,0.9)]' : 'text-muted hover:text-ink'
            }`}
          >
            {option.label}
          </button>
        ))}
      </div>

      <form onSubmit={(event) => void submit(event)} className="mt-6 space-y-5">
        <Field label="Demo email" required>
          <div className="relative">
            <Mail size={16} className="absolute top-1/2 left-4 -translate-y-1/2 text-muted" />
            <Input
              type="email"
              value={email}
              onChange={(event) => setEmail(event.target.value)}
              placeholder="ramesh@demo.krishi360.in"
              className="pl-11"
              autoComplete="email"
            />
          </div>
        </Field>
        <Field label="Demo password" required>
          <div className="relative">
            <LockKeyhole size={16} className="absolute top-1/2 left-4 -translate-y-1/2 text-muted" />
            <Input
              type="password"
              value={password}
              onChange={(event) => setPassword(event.target.value)}
              placeholder="Any password works in demo mode"
              className="pl-11"
              autoComplete="current-password"
            />
          </div>
        </Field>

        {error ? <p className="rounded-2xl bg-[#FBE7E3] px-4 py-3 text-xs font-semibold text-alert">{error}</p> : null}

        <div className="flex items-center justify-between">
          <label className="flex items-center gap-2 text-xs font-semibold text-muted">
            <input type="checkbox" defaultChecked className="size-4 accent-[#344B35]" />
            Remember this demo role
          </label>
          <Link to="/forgot-password" className="text-xs font-extrabold text-forest hover:underline">Forgot password?</Link>
        </div>

        <Button type="submit" size="lg" className="w-full" disabled={loading}>
          {loading ? 'Signing in…' : 'Sign in'} <ArrowRight size={17} />
        </Button>
      </form>

      <div className="my-7 flex items-center gap-3 text-[10px] font-extrabold tracking-[0.14em] text-muted uppercase">
        <span className="h-px flex-1 bg-line" /> or enter instantly <span className="h-px flex-1 bg-line" />
      </div>

      <div className="grid gap-2 sm:grid-cols-3">
        {roleOptions.map((option) => (
          <button
            key={option.id}
            type="button"
            disabled={loading}
            onClick={() => void quick(option.id)}
            className={`${buttonClasses('secondary', 'sm', 'flex-col items-start gap-1 py-3 text-left')}`}
          >
            <Sparkles size={14} />
            <span>{option.label} demo</span>
          </button>
        ))}
      </div>
      <p className="mt-4 text-center text-[11px] leading-relaxed text-muted">
        Simulated authentication only. No credentials are transmitted or verified.
      </p>
    </AuthShell>
  )
}

import { useState } from 'react'
import type { FormEvent } from 'react'
import { ArrowRight } from 'lucide-react'
import { Link, useNavigate } from 'react-router-dom'
import { useAuth } from '../../context/AuthContext'
import { useToast } from '../../context/ToastContext'
import { Button } from '../../components/ui/Button'
import { Field, Input, Select } from '../../components/ui/Input'
import type { Role } from '../../types'
import { AuthShell } from './AuthShell'

export function RegisterPage() {
  const [role, setRole] = useState<Role>('farmer')
  const [name, setName] = useState('')
  const [email, setEmail] = useState('')
  const [location, setLocation] = useState('')
  const [password, setPassword] = useState('')
  const [confirm, setConfirm] = useState('')
  const [error, setError] = useState('')
  const { register, loading } = useAuth()
  const { show } = useToast()
  const navigate = useNavigate()

  const submit = async (event: FormEvent) => {
    event.preventDefault()
    setError('')
    if (password.length < 8) return setError('Use at least 8 characters for the demo password.')
    if (password !== confirm) return setError('Passwords do not match.')
    try {
      const user = await register({ name, email, password, role, location })
      show('Demo account created', `Welcome, ${user.name}. Let's finish setup.`, 'success')
      navigate('/onboarding')
    } catch (cause) {
      setError(cause instanceof Error ? cause.message : 'Could not create account.')
    }
  }

  return (
    <AuthShell
      eyebrow="Create account"
      title="Start your demo journey"
      description="Choose a role and create a local demo profile. This information is not sent to any server."
      footer={
        <>
          Already have a demo profile?{' '}
          <Link to="/login" className="font-extrabold text-forest hover:underline">Sign in</Link>
        </>
      }
    >
      <form onSubmit={(event) => void submit(event)} className="space-y-5">
        <Field label="I am joining as" required>
          <Select
            value={role}
            onChange={(event) => setRole(event.target.value as Role)}
            options={[
              { value: 'farmer', label: 'Farmer' },
              { value: 'expert', label: 'Agriculture Expert' },
              { value: 'admin', label: 'Administrator' },
            ]}
          />
        </Field>
        <Field label="Full name" required>
          <Input value={name} onChange={(event) => setName(event.target.value)} placeholder="Your name" />
        </Field>
        <Field label="Email address" required>
          <Input type="email" value={email} onChange={(event) => setEmail(event.target.value)} placeholder="you@example.in" />
        </Field>
        <Field label="Location" hint="Optional for this demo">
          <Input value={location} onChange={(event) => setLocation(event.target.value)} placeholder="District, State" />
        </Field>
        <div className="grid gap-5 sm:grid-cols-2">
          <Field label="Password" required>
            <Input type="password" value={password} onChange={(event) => setPassword(event.target.value)} placeholder="8+ characters" />
          </Field>
          <Field label="Confirm password" required>
            <Input type="password" value={confirm} onChange={(event) => setConfirm(event.target.value)} placeholder="Repeat password" />
          </Field>
        </div>
        {error ? <p className="rounded-2xl bg-[#FBE7E3] px-4 py-3 text-xs font-semibold text-alert">{error}</p> : null}
        <Button type="submit" size="lg" className="w-full" disabled={loading}>
          {loading ? 'Creating profile…' : 'Create demo account'} <ArrowRight size={17} />
        </Button>
      </form>
    </AuthShell>
  )
}

