import { Button } from '../../components/ui/Button'
import { Field, Input } from '../../components/ui/Input'
import { AuthShell } from './AuthShell'

export function ForgotPasswordPage() {
  const [email, setEmail] = useState('')
  const [error, setError] = useState('')
  const [sent, setSent] = useState(false)
  const [loading, setLoading] = useState(false)

  const submit = async (event: FormEvent) => {
    event.preventDefault()
    setError('')
    setLoading(true)
    try {
      await authService.requestPasswordReset(email)
      setSent(true)
    } catch (cause) {
      setError(cause instanceof Error ? cause.message : 'Could not continue.')
    } finally {
      setLoading(false)
    }
  }

  return (
    <AuthShell
      eyebrow="Account recovery"
      title="Reset your demo password"
      description="This screen simulates a recovery flow. No email is sent in the frontend-only build."
      footer={<Link to="/login" className="font-extrabold text-forest hover:underline">Back to sign in</Link>}
    >
      {sent ? (
        <div className="rounded-3xl bg-soft-sage/70 p-6 text-center">
          <CheckCircle2 size={32} className="mx-auto text-forest" />
          <h2 className="mt-4 text-lg font-extrabold text-ink">Demo reset link ready</h2>
          <p className="mt-2 text-sm leading-relaxed text-muted">
            In a production build, a secure link would be sent to {email}. Continue to the simulated reset screen.
          </p>
          <Link to="/reset-password" className="mt-6 inline-flex items-center gap-2 rounded-2xl bg-forest px-6 py-3 text-sm font-bold text-white">
            Continue <ArrowRight size={15} />
          </Link>
        </div>
      ) : (
        <form onSubmit={(event) => void submit(event)} className="space-y-5">
          <Field label="Email address" required>
            <Input type="email" value={email} onChange={(event) => setEmail(event.target.value)} placeholder="you@example.in" />
          </Field>
          {error ? <p className="rounded-2xl bg-[#FBE7E3] px-4 py-3 text-xs font-semibold text-alert">{error}</p> : null}
          <Button type="submit" size="lg" className="w-full" disabled={loading}>
            {loading ? 'Checking…' : 'Continue'} <ArrowRight size={16} />
          </Button>
        </form>
      )}
    </AuthShell>
  )
}

import { useState } from 'react'
import type { FormEvent } from 'react'
import { ArrowRight } from 'lucide-react'
import { Link, useNavigate } from 'react-router-dom'
import { authService } from '../../services/authService'
import { useToast } from '../../context/ToastContext'
import { Button } from '../../components/ui/Button'
import { Field, Input } from '../../components/ui/Input'
import { AuthShell } from './AuthShell'

export function ResetPasswordPage() {
  const [password, setPassword] = useState('')
  const [confirm, setConfirm] = useState('')
  const [error, setError] = useState('')
  const [loading, setLoading] = useState(false)
  const { show } = useToast()
  const navigate = useNavigate()

  const submit = async (event: FormEvent) => {
    event.preventDefault()
    setError('')
    setLoading(true)
    try {
      await authService.resetPassword(password, confirm)
      show('Demo password updated', 'You can now sign in with the demo experience.', 'success')
      navigate('/login')
    } catch (cause) {
      setError(cause instanceof Error ? cause.message : 'Could not reset password.')
    } finally {
      setLoading(false)
    }
  }

  return (
    <AuthShell
      eyebrow="New password"
      title="Choose a demo password"
      description="Pick any password with at least eight characters. This simulation never stores or transmits it."
      footer={<Link to="/login" className="font-extrabold text-forest hover:underline">Back to sign in</Link>}
    >
      <form onSubmit={(event) => void submit(event)} className="space-y-5">
        <Field label="New password" required>
          <Input type="password" value={password} onChange={(event) => setPassword(event.target.value)} placeholder="At least 8 characters" />
        </Field>
        <Field label="Confirm new password" required>
          <Input type="password" value={confirm} onChange={(event) => setConfirm(event.target.value)} placeholder="Repeat password" />
        </Field>
        {error ? <p className="rounded-2xl bg-[#FBE7E3] px-4 py-3 text-xs font-semibold text-alert">{error}</p> : null}
        <Button type="submit" size="lg" className="w-full" disabled={loading}>
          {loading ? 'Updating…' : 'Reset demo password'} <ArrowRight size={16} />
        </Button>
      </form>
    </AuthShell>
  )
}

import type { ReactNode } from 'react'
import { RotateCcw, Search } from 'lucide-react'
import { Input, Select } from '../ui/Input'
import type { SelectOption } from '../ui/Input'

export interface FilterSelect {
  label: string
  value: string
  onChange: (value: string) => void
  options: SelectOption[]
}

export function FilterBar({
  search,
  onSearch,
  placeholder = 'Search…',
  selects = [],
  onReset,
  children,
}: {
  search: string
  onSearch: (value: string) => void
  placeholder?: string
  selects?: FilterSelect[]
  onReset?: () => void
  children?: ReactNode
}) {
  return (
    <div className="clay-card mb-5 flex flex-col gap-3 p-4">
      <div className="grid gap-3 md:grid-cols-[minmax(200px,1.3fr)_repeat(auto-fit,minmax(150px,1fr))]">
        <div className="relative">
          <Search size={16} className="absolute top-1/2 left-4 -translate-y-1/2 text-muted" />
          <Input value={search} onChange={(event) => onSearch(event.target.value)} placeholder={placeholder} className="pl-11" />
        </div>
        {selects.map((filter) => (
          <Select key={filter.label} value={filter.value} onChange={(event) => filter.onChange(event.target.value)} options={filter.options} aria-label={filter.label} />
        ))}
      </div>
      {(onReset || children) && (
        <div className="flex flex-wrap items-center justify-between gap-3 border-t border-line/60 pt-3">
          {children}
          {onReset ? (
            <button type="button" onClick={onReset} className="inline-flex items-center gap-2 text-xs font-bold text-muted transition-colors hover:text-forest">
              <RotateCcw size={13} /> Reset filters
            </button>
          ) : <span />}
        </div>
      )}
    </div>
  )
}

import { useMemo, useState } from 'react'
import { CalendarRange, Droplets, Info, Leaf, Plus, Sprout } from 'lucide-react'
import { PageHeader } from '../../components/common/PageHeader'
import { DemoNote } from '../../components/common/DemoNote'
import { FilterBar } from '../../components/common/FilterBar'
import { Card } from '../../components/ui/Card'
import { Badge } from '../../components/ui/Badge'
import { Modal } from '../../components/ui/Modal'
import { Button } from '../../components/ui/Button'
import { Field, Input, Select } from '../../components/ui/Input'
import { useToast } from '../../context/ToastContext'
import { CROPS, CROP_NAMES } from '../../data/crops'
import { DEMO_FARM } from '../../data/farmers'
import type { Crop } from '../../types'

export function MyCrops() {
  const [query, setQuery] = useState('')
  const [category, setCategory] = useState('All categories')
  const [selected, setSelected] = useState<Crop | null>(null)
  const [addOpen, setAddOpen] = useState(false)
  const [customCrops, setCustomCrops] = useState<Crop[]>([])
  const [newName, setNewName] = useState('')
  const { show } = useToast()

  const crops = useMemo(() => [...DEMO_FARM.plots.map((plot) => plot.crop), ...customCrops.map((crop) => crop.name)], [customCrops])
  const filtered = useMemo(() => {
    const catalog = [...CROPS, ...customCrops]
    return catalog.filter((crop) => {
      const matchesName = crops.includes(crop.name)
      const matchesCategory = category === 'All categories' || crop.category === category
      const matchesQuery = !query.trim() || crop.name.toLowerCase().includes(query.trim().toLowerCase())
      return matchesName && matchesCategory && matchesQuery
    })
  }, [CROPS, customCrops, crops, category, query])

  const categories = ['All categories', ...Array.from(new Set([...CROPS, ...customCrops].map((crop) => crop.category)))]

  const addCrop = () => {
    if (!newName.trim()) return show('Crop name required', 'Enter a crop name to add it to the demo list.', 'warning')
    const crop: Crop = {
      id: `crop-custom-${Date.now()}`,
      name: newName.trim(),
      category: 'Other',
      season: 'Not specified',
      durationDays: 0,
      waterNeed: 'medium',
      icon: 'sprout',
    }
    setCustomCrops((current) => [crop, ...current])
    setNewName('')
    setAddOpen(false)
    show('Crop added', `${crop.name} is now in your demo crop list.`, 'success')
  }

  return (
    <div>
      <PageHeader
        eyebrow="Crop records"
        title="My Crops"
        description="Crops currently linked to your plots, with quick access to demo advisory context."
        badge={<DemoNote label="Sample catalog" />}
        actions={<Button onClick={() => setAddOpen(true)}><Plus size={16} /> Add crop</Button>}
      />

      <FilterBar
        search={query}
        onSearch={setQuery}
        placeholder="Search your crops…"
        selects={[{ label: 'Category', value: category, onChange: setCategory, options: categories.map((item) => ({ value: item, label: item })) }]}
        onReset={() => { setQuery(''); setCategory('All categories') }}
      />

      <div className="grid gap-5 md:grid-cols-2 xl:grid-cols-3">
        {filtered.map((crop) => {
          const plot = DEMO_FARM.plots.find((item) => item.crop === crop.name)
          return (
            <Card key={crop.id} interactive className="flex h-full flex-col">
              <div className="flex items-start justify-between gap-3">
                <span className="flex size-12 items-center justify-center rounded-2xl bg-soft-sage text-forest"><Sprout size={22} /></span>
                <Badge tone="sage">{crop.category}</Badge>
              </div>
              <h2 className="mt-5 text-xl font-extrabold tracking-tight text-ink">{crop.name}</h2>
              <p className="mt-2 flex-1 text-sm leading-relaxed text-muted">
                {plot ? `Growing in ${plot.name} · ${plot.areaHa} ha · ${plot.growthStage}.` : 'Added to your demo crop list. Link it to a plot from My Farm.'}
              </p>
              <div className="mt-5 grid grid-cols-2 gap-3 text-xs">
                <div className="rounded-2xl bg-soft-sage/45 p-3">
                  <Droplets size={15} className="text-forest" />
                  <p className="mt-2 font-bold text-ink">{crop.waterNeed} water need</p>
                </div>
                <div className="rounded-2xl bg-soft-sage/45 p-3">
                  <CalendarRange size={15} className="text-forest" />
                  <p className="mt-2 font-bold text-ink">{crop.durationDays || '—'} days</p>
                </div>
              </div>
              <button type="button" onClick={() => setSelected(crop)} className="mt-5 inline-flex items-center gap-2 text-xs font-extrabold text-forest hover:underline">
                <Info size={14} /> View crop details
              </button>
            </Card>
          )
        })}
      </div>

      {filtered.length === 0 ? (
        <Card className="mt-5 text-center">
          <Leaf size={28} className="mx-auto text-forest" />
          <p className="mt-3 text-sm font-bold text-ink">No crops match these filters.</p>
          <p className="mt-1 text-xs text-muted">Try a different category or clear the search.</p>
        </Card>
      ) : null}

      <Modal open={selected !== null} onClose={() => setSelected(null)} title={selected?.name ?? 'Crop details'} description="Sample crop catalogue information.">
        {selected ? (
          <div className="space-y-4">
            <div className="grid gap-3 sm:grid-cols-2">
              {[
                { label: 'Category', value: selected.category },
                { label: 'Season', value: selected.season },
                { label: 'Duration', value: selected.durationDays ? `${selected.durationDays} days` : 'Not specified' },
                { label: 'Water need', value: selected.waterNeed },
              ].map((item) => (
                <div key={item.label} className="rounded-2xl bg-soft-sage/45 p-4">
                  <p className="text-[10px] font-extrabold tracking-wide text-muted uppercase">{item.label}</p>
                  <p className="mt-1.5 text-sm font-bold text-ink capitalize">{item.value}</p>
                </div>
              ))}
            </div>
            <div className="rounded-2xl border border-line/70 p-4 text-xs leading-relaxed text-muted">
              This catalogue entry is demo data. Advisory outputs in CropDoctor AI and JalSense use the crop name as context only.
            </div>
          </div>
        ) : null}
      </Modal>

      <Modal open={addOpen} onClose={() => setAddOpen(false)} title="Add a demo crop" description="Add a crop name to your session-only list.">
        <Field label="Crop name" required>
          <Input value={newName} onChange={(event) => setNewName(event.target.value)} placeholder="e.g. Soybean" />
        </Field>
        <div className="mt-5 flex justify-end gap-2">
          <Button variant="ghost" onClick={() => setAddOpen(false)}>Cancel</Button>
          <Button onClick={addCrop}>Add crop</Button>
        </div>
      </Modal>
    </div>
  )
}

import { useMemo, useState } from 'react'
import { AlertTriangle, Bell, CheckCircle2, Info, XCircle } from 'lucide-react'
import { PageHeader } from '../../components/common/PageHeader'
import { Badge } from '../../components/ui/Badge'
import { Button } from '../../components/ui/Button'
import { Tabs } from '../../components/ui/Tabs'
import { Card } from '../../components/ui/Card'
import { useApp } from '../../services/store'
import { useToast } from '../../context/ToastContext'
import { formatDateTime, relativeTime } from '../../services/utils'
import type { NotificationItem, Severity } from '../../types'

const icons: Record<Severity, typeof Bell> = {
  info: Info,
  success: CheckCircle2,
  warning: AlertTriangle,
  critical: XCircle,
}

const tones: Record<Severity, 'info' | 'success' | 'warning' | 'critical'> = {
  info: 'info',
  success: 'success',
  warning: 'warning',
  critical: 'critical',
}

export function NotificationsPage() {
  const { notifications, markNotificationRead, markAllNotificationsRead } = useApp()
  const { show } = useToast()
  const [tab, setTab] = useState('all')

  const items = useMemo(() => {
    const visible = notifications.filter((item) => item.audience === 'farmer' || item.audience === 'all')
    if (tab === 'unread') return visible.filter((item) => !item.read)
    if (tab === 'critical') return visible.filter((item) => item.severity === 'critical' || item.severity === 'warning')
    return visible
  }, [notifications, tab])

  const unread = notifications.filter((item) => (item.audience === 'farmer' || item.audience === 'all') && !item.read).length

  const markAll = () => {
    markAllNotificationsRead('farmer')
    show('Notifications updated', 'All visible farmer notifications are marked as read.', 'success')
  }

  const markOne = (item: NotificationItem) => {
    markNotificationRead(item.id)
    show('Marked as read', item.title, 'info')
  }

  return (
    <div>
      <PageHeader
        eyebrow="Support"
        title="Notifications"
        description="Alerts and updates from your simulated farm workspace."
        actions={<Button variant="outline" onClick={markAll} disabled={unread === 0}><CheckCircle2 size={15} /> Mark all read</Button>}
      />

      <Tabs
        items={[
          { id: 'all', label: `All (${notifications.filter((item) => item.audience === 'farmer' || item.audience === 'all').length})` },
          { id: 'unread', label: `Unread (${unread})` },
          { id: 'critical', label: 'Warnings & alerts' },
        ]}
        activeId={tab}
        onChange={setTab}
        className="mb-5 max-w-lg"
      />

      <div className="space-y-3">
        {items.map((item) => {
          const Icon = icons[item.severity]
          return (
            <Card key={item.id} className={item.read ? 'opacity-75' : 'border-sage/50'}>
              <div className="flex items-start gap-4">
                <span className={`flex size-11 shrink-0 items-center justify-center rounded-2xl ${
                  item.severity === 'critical' ? 'bg-[#FBE7E3] text-alert' : item.severity === 'warning' ? 'bg-[#FBF1DC] text-[#8A6520]' : 'bg-soft-sage text-forest'
                }`}>
                  <Icon size={19} />
                </span>
                <div className="min-w-0 flex-1">
                  <div className="flex flex-wrap items-center gap-2">
                    <h2 className="text-sm font-extrabold text-ink">{item.title}</h2>
                    <Badge tone={tones[item.severity]}>{item.severity}</Badge>
                    {!item.read ? <span className="size-2 rounded-full bg-sage" /> : null}
                  </div>
                  <p className="mt-2 text-sm leading-relaxed text-muted">{item.body}</p>
                  <p className="mt-2 text-[11px] text-muted">{relativeTime(item.createdAt)} · {formatDateTime(item.createdAt)}</p>
                </div>
                {!item.read ? (
                  <Button variant="ghost" size="sm" onClick={() => markOne(item)}>Mark read</Button>
                ) : null}
              </div>
            </Card>
          )
        })}
        {items.length === 0 ? (
          <Card className="py-14 text-center">
            <Bell size={28} className="mx-auto text-forest" />
            <p className="mt-3 text-sm font-bold text-ink">Nothing in this view.</p>
            <p className="mt-1 text-xs text-muted">Adjust the tab to see other notifications.</p>
          </Card>
        ) : null}
      </div>
    </div>
  )
}

import { useRef, useState } from 'react'
import type { FormEvent } from 'react'
import { Bot, Send, Sparkles, UserRound } from 'lucide-react'
import { PageHeader } from '../../components/common/PageHeader'
import { DemoNote } from '../../components/common/DemoNote'
import { Card } from '../../components/ui/Card'
import { Button } from '../../components/ui/Button'
import { Input } from '../../components/ui/Input'
import { useApp } from '../../services/store'
import { useToast } from '../../context/ToastContext'
import type { ChatMessage } from '../../types'

const suggestions = [
  'What should I check before irrigating wheat?',
  'How do I prepare a crop health case?',
  'Which storage batch needs attention?',
  'How can I compare mandi prices?',
]

function answerFor(text: string, criticalBatches: number, cases: number): string {
  const query = text.toLowerCase()
  if (query.includes('irrigat') || query.includes('water')) {
    return 'In this demo, open JalSense and enter your plot, crop stage, soil type and simulated moisture. The recommendation explains its reasoning. Always verify field conditions locally before irrigating.'
  }
  if (query.includes('case') || query.includes('disease') || query.includes('leaf')) {
    return `You currently have ${cases} demo crop case${cases === 1 ? '' : 's'}. In CropDoctor AI, upload a clear image, choose the crop and plant part, add symptoms, then review the labelled simulation. Submitting creates a case for expert review.`
  }
  if (query.includes('storage') || query.includes('batch') || query.includes('humidity')) {
    return criticalBatches > 0
      ? `GrainGuard shows ${criticalBatches} batch above a demo threshold. Open the batch to inspect simulated temperature, humidity and log an inspection. These are not real sensor readings.`
      : 'All demo batches are currently within their configured thresholds. You can still create a batch and test how changing values affects its status.'
  }
  if (query.includes('mandi') || query.includes('price') || query.includes('market')) {
    return 'MandiSmart lets you filter demo prices by crop, state and district, compare modal prices and estimate revenue after a transport cost. Price records are sample data, not live market quotes.'
  }
  if (query.includes('scheme') || query.includes('government')) {
    return 'SchemeSaathi contains sample scheme entries with source links. Check official government portals for current eligibility, documents and terms before applying.'
  }
  return 'I can help you navigate the five demo modules, explain a simulated result or point you to the right portal. Try one of the suggested questions above.'
}

export function AssistantPage() {
  const { storageBatches, cases } = useApp()
  const { show } = useToast()
  const criticalBatches = storageBatches.filter((batch) => batch.status === 'critical').length
  const [messages, setMessages] = useState<ChatMessage[]>([
    {
      id: 'welcome',
      sender: 'assistant',
      text: 'Hello! I am the KRISHI360 AI demo assistant. I can explain module results and help you navigate this frontend. I do not provide verified diagnoses or live data.',
      time: new Date().toLocaleTimeString('en-IN', { hour: '2-digit', minute: '2-digit' }),
    },
  ])
  const [input, setInput] = useState('')
  const [typing, setTyping] = useState(false)
  const timer = useRef<number | null>(null)

  const send = (text: string) => {
    const clean = text.trim()
    if (!clean) return
    const time = new Date().toLocaleTimeString('en-IN', { hour: '2-digit', minute: '2-digit' })
    setMessages((current) => [...current, { id: `u-${Date.now()}`, sender: 'user', text: clean, time }])
    setInput('')
    setTyping(true)
    if (timer.current) window.clearTimeout(timer.current)
    timer.current = window.setTimeout(() => {
      setMessages((current) => [
        ...current,
        {
          id: `a-${Date.now()}`,
          sender: 'assistant',
          text: answerFor(clean, criticalBatches, cases.length),
          time: new Date().toLocaleTimeString('en-IN', { hour: '2-digit', minute: '2-digit' }),
        },
      ])
      setTyping(false)
    }, 750)
  }

  const submit = (event: FormEvent) => {
    event.preventDefault()
    send(input)
  }

  return (
    <div>
      <PageHeader
        eyebrow="Support"
        title="AI Agriculture Assistant"
        description="A guided demo conversation built on the same simulated data used across the platform."
        badge={<DemoNote label="Rule-based demo replies" />}
        actions={<Button variant="outline" onClick={() => { setMessages((current) => [current[0]]); show('Conversation cleared', 'A fresh demo chat is ready.', 'info') }}>New conversation</Button>}
      />

      <div className="grid gap-6 xl:grid-cols-[1fr_300px]">
        <Card padded={false} className="flex min-h-[560px] flex-col overflow-hidden">
          <div className="flex items-center gap-3 border-b border-line/70 bg-soft-sage/35 px-5 py-4">
            <span className="flex size-10 items-center justify-center rounded-2xl bg-forest text-white"><Bot size={19} /></span>
            <div>
              <p className="text-sm font-extrabold text-ink">Krishi Assistant</p>
              <p className="text-[11px] text-muted">Demo mode · Answers generated from local rules</p>
            </div>
            <span className="ml-auto flex items-center gap-1.5 text-[11px] font-bold text-forest"><span className="size-2 rounded-full bg-sage" /> Online</span>
          </div>

          <div className="scroll-thin flex-1 space-y-4 overflow-y-auto p-5">
            {messages.map((message) => (
              <div key={message.id} className={`flex gap-3 ${message.sender === 'user' ? 'flex-row-reverse' : ''}`}>
                <span className={`flex size-8 shrink-0 items-center justify-center rounded-xl ${message.sender === 'user' ? 'bg-soft-sage text-forest' : 'bg-forest text-white'}`}>
                  {message.sender === 'user' ? <UserRound size={15} /> : <Bot size={15} />}
                </span>
                <div className={`max-w-[85%] rounded-2xl px-4 py-3 ${message.sender === 'user' ? 'bg-forest text-white' : 'bg-soft-sage/60 text-ink'}`}>
                  <p className="text-sm leading-relaxed">{message.text}</p>
                  <p className={`mt-2 text-[10px] ${message.sender === 'user' ? 'text-white/60' : 'text-muted'}`}>{message.time}</p>
                </div>
              </div>
            ))}
            {typing ? (
              <div className="flex gap-3">
                <span className="flex size-8 items-center justify-center rounded-xl bg-forest text-white"><Bot size={15} /></span>
                <div className="flex items-center gap-1.5 rounded-2xl bg-soft-sage/60 px-4 py-3">
                  {[0, 1, 2].map((index) => <span key={index} className="size-1.5 animate-bounce rounded-full bg-forest" style={{ animationDelay: `${index * 120}ms` }} />)}
                </div>
              </div>
            ) : null}
          </div>

          <form onSubmit={submit} className="flex gap-3 border-t border-line/70 bg-white/50 p-4">
            <Input value={input} onChange={(event) => setInput(event.target.value)} placeholder="Ask about a module or demo result…" aria-label="Assistant message" />
            <Button type="submit" aria-label="Send message" disabled={!input.trim() || typing}><Send size={17} /></Button>
          </form>
        </Card>

        <div className="space-y-5">
          <Card>
            <div className="flex items-center gap-2 text-forest"><Sparkles size={17} /><h2 className="text-sm font-extrabold text-ink">Suggested questions</h2></div>
            <div className="mt-4 space-y-2">
              {suggestions.map((suggestion) => (
                <button key={suggestion} type="button" onClick={() => send(suggestion)} className="w-full rounded-2xl border border-line/70 bg-white/60 px-4 py-3 text-left text-xs font-semibold text-ink transition-colors hover:border-sage hover:bg-soft-sage/40">
                  {suggestion}
                </button>
              ))}
            </div>
          </Card>
          <Card className="bg-forest text-white">
            <p className="text-[11px] font-extrabold tracking-[0.12em] text-sage uppercase">Important</p>
            <p className="mt-3 text-xs leading-relaxed text-white/75">
              This assistant does not provide verified diagnosis, pesticide dosages, live prices or real sensor interpretation. Consult qualified local experts for field decisions.
            </p>
          </Card>
        </div>
      </div>
    </div>
  )
}

