import { useMemo, useState } from 'react'
import { ArrowUpRight, Bookmark, BookmarkCheck, CheckCircle2, ExternalLink, FileText, Landmark, Search } from 'lucide-react'
import { PageHeader } from '../../components/common/PageHeader'
import { DemoNote } from '../../components/common/DemoNote'
import { FilterBar } from '../../components/common/FilterBar'
import { Card, CardHeader } from '../../components/ui/Card'
import { Badge } from '../../components/ui/Badge'
import { Button } from '../../components/ui/Button'
import { Progress } from '../../components/ui/Progress'
import { Modal } from '../../components/ui/Modal'
import { useApp } from '../../services/store'
import { useToast } from '../../context/ToastContext'
import { schemeService } from '../../services/schemeService'
import { SCHEME_CATEGORIES, SCHEME_STATES } from '../../data/schemes'
import { formatDate } from '../../services/utils'
import type { Scheme } from '../../types'

export function SchemeSaathiPage() {
  const { schemes, savedSchemeIds, applications, saveScheme, unsaveScheme, startApplication, advanceApplication } = useApp()
  const { show } = useToast()
  const [query, setQuery] = useState('')
  const [category, setCategory] = useState('All categories')
  const [state, setState] = useState('All states')
  const [selected, setSelected] = useState<Scheme | null>(null)

  const filtered = useMemo(
    () => schemeService.filter(schemes, { query, category, state }),
    [schemes, query, category, state],
  )

  const toggleSave = (scheme: Scheme) => {
    const saved = savedSchemeIds.includes(scheme.id)
    if (saved) {
      unsaveScheme(scheme.id)
      show('Scheme removed', `${scheme.name} removed from saved schemes.`, 'info')
    } else {
      saveScheme(scheme.id)
      show('Scheme saved', `${scheme.name} added to your saved list.`, 'success')
    }
  }

  const start = (scheme: Scheme) => {
    startApplication(scheme.id, 'farmer-001')
    show('Demo tracker started', `Track sample application steps for ${scheme.name}.`, 'success')
  }

  const advance = (applicationId: string) => {
    advanceApplication(applicationId)
    show('Progress updated', 'Demo application moved to the next stage.', 'success')
  }

  return (
    <div>
      <PageHeader
        eyebrow="Module 05 · Government support"
        title="SchemeSaathi"
        description="Discover sample agriculture scheme entries, inspect document checklists and track a demo application."
        badge={<DemoNote label="Sample scheme information" />}
      />

      <div className="grid gap-4 sm:grid-cols-3">
        {[
          { label: 'Available entries', value: schemes.length, detail: 'Illustrative scheme records' },
          { label: 'Saved schemes', value: savedSchemeIds.length, detail: 'Saved in this session' },
          { label: 'Application trackers', value: applications.length, detail: 'No submissions are made' },
        ].map((item) => (
          <Card key={item.label}>
            <p className="text-[11px] font-extrabold tracking-[0.08em] text-muted uppercase">{item.label}</p>
            <p className="mt-3 text-3xl font-extrabold tracking-tight text-ink">{item.value}</p>
            <p className="mt-1 text-xs text-muted">{item.detail}</p>
          </Card>
        ))}
      </div>

      <div className="mt-6">
        <FilterBar
          search={query}
          onSearch={setQuery}
          placeholder="Search schemes or tags…"
          selects={[
            { label: 'Category', value: category, onChange: setCategory, options: [{ value: 'All categories', label: 'All categories' }, ...SCHEME_CATEGORIES.map((name) => ({ value: name, label: name }))] },
            { label: 'State', value: state, onChange: setState, options: [{ value: 'All states', label: 'All states' }, ...SCHEME_STATES.map((name) => ({ value: name, label: name }))] },
          ]}
          onReset={() => { setQuery(''); setCategory('All categories'); setState('All states') }}
        />
      </div>

      <div className="grid gap-6 xl:grid-cols-[1.2fr_0.8fr]">
        <div className="grid gap-4 md:grid-cols-2">
          {filtered.map((scheme) => {
            const saved = savedSchemeIds.includes(scheme.id)
            const application = applications.find((item) => item.schemeId === scheme.id)
            return (
              <Card key={scheme.id} interactive className="flex h-full flex-col">
                <div className="flex items-start justify-between gap-3">
                  <span className="flex size-11 items-center justify-center rounded-2xl bg-soft-sage text-forest"><Landmark size={20} /></span>
                  <button
                    type="button"
                    onClick={() => toggleSave(scheme)}
                    aria-label={saved ? 'Unsave scheme' : 'Save scheme'}
                    className={`flex size-9 items-center justify-center rounded-xl transition-colors ${saved ? 'bg-forest text-white' : 'bg-soft-sage text-forest'}`}
                  >
                    {saved ? <BookmarkCheck size={16} /> : <Bookmark size={16} />}
                  </button>
                </div>
                <h2 className="mt-5 text-lg font-extrabold tracking-tight text-ink">{scheme.name}</h2>
                <div className="mt-2 flex flex-wrap gap-2">
                  <Badge tone="sage">{scheme.category}</Badge>
                  <Badge tone="neutral">{scheme.state}</Badge>
                </div>
                <p className="mt-3 flex-1 text-xs leading-relaxed text-muted">{scheme.summary}</p>
                {application ? (
                  <div className="mt-4 rounded-2xl bg-soft-sage/45 p-3">
                    <Progress value={application.progress} label={application.stage} />
                  </div>
                ) : null}
                <div className="mt-5 flex flex-wrap gap-2">
                  <Button size="sm" variant="outline" onClick={() => setSelected(scheme)}>View details</Button>
                  {application ? (
                    <Button size="sm" variant="secondary" onClick={() => advance(application.id)} disabled={application.progress >= 100}>
                      {application.progress >= 100 ? 'Demo submitted' : 'Advance step'}
                    </Button>
                  ) : (
                    <Button size="sm" onClick={() => start(scheme)}>Start tracker</Button>
                  )}
                </div>
              </Card>
            )
          })}
          {filtered.length === 0 ? (
            <Card className="md:col-span-2 py-14 text-center">
              <Search size={28} className="mx-auto text-forest" />
              <p className="mt-3 text-sm font-bold text-ink">No scheme entries match.</p>
              <p className="mt-1 text-xs text-muted">Try clearing a filter or searching a different term.</p>
            </Card>
          ) : null}
        </div>

        <div className="space-y-6">
          <Card>
            <CardHeader title="Application tracker" description="Demo progress only — nothing is submitted." icon={<CheckCircle2 size={18} />} />
            <div className="space-y-3">
              {applications.map((app) => {
                const scheme = schemes.find((item) => item.id === app.schemeId)
                return (
                  <div key={app.id} className="rounded-2xl border border-line/70 bg-white/60 p-4">
                    <p className="text-sm font-extrabold text-ink">{scheme?.name ?? app.schemeId}</p>
                    <p className="mt-1 text-[11px] text-muted">Updated {formatDate(app.updatedAt)}</p>
                    <div className="mt-4"><Progress value={app.progress} label={app.stage} /></div>
                    <Button size="sm" variant="ghost" className="mt-3" onClick={() => advance(app.id)} disabled={app.progress >= 100}>
                      {app.progress >= 100 ? 'Demo complete' : 'Advance application'}
                    </Button>
                  </div>
                )
              })}
              {applications.length === 0 ? <p className="py-8 text-center text-sm text-muted">No trackers started yet.</p> : null}
            </div>
          </Card>

          <Card className="bg-forest text-white">
            <p className="text-[11px] font-extrabold tracking-[0.14em] text-sage uppercase">Verify officially</p>
            <h3 className="mt-3 text-xl font-extrabold tracking-tight">Sample information only</h3>
            <p className="mt-3 text-xs leading-relaxed text-white/75">
              Scheme summaries and checklists are illustrative. KRISHI360 AI does not publish deadlines, benefit amounts or eligibility guarantees. Always confirm on an official government source.
            </p>
            <a href="https://www.india.gov.in/" target="_blank" rel="noreferrer" className="mt-5 inline-flex items-center gap-2 rounded-2xl bg-white/12 px-4 py-2.5 text-xs font-bold text-white hover:bg-white/20">
              Official information portal <ExternalLink size={14} />
            </a>
          </Card>
        </div>
      </div>

      <Modal open={selected !== null} onClose={() => setSelected(null)} title={selected?.name ?? 'Scheme details'} description="Sample scheme entry with official source pointer." size="lg">
        {selected ? (
          <div className="space-y-5">
            <div className="flex flex-wrap gap-2">
              <Badge tone="sage">{selected.category}</Badge>
              <Badge tone="neutral">{selected.state}</Badge>
            </div>
            <p className="text-sm leading-relaxed text-ink">{selected.summary}</p>
            <div className="grid gap-4 sm:grid-cols-2">
              <div className="rounded-2xl bg-soft-sage/45 p-4">
                <h3 className="flex items-center gap-2 text-sm font-extrabold text-ink"><CheckCircle2 size={16} /> Eligibility overview</h3>
                <ul className="mt-3 space-y-2 text-xs text-muted">
                  {selected.eligibility.map((item) => <li key={item}>• {item}</li>)}
                </ul>
              </div>
              <div className="rounded-2xl bg-soft-sage/45 p-4">
                <h3 className="flex items-center gap-2 text-sm font-extrabold text-ink"><FileText size={16} /> Document checklist</h3>
                <ul className="mt-3 space-y-2 text-xs text-muted">
                  {selected.documents.map((item) => <li key={item}>• {item}</li>)}
                </ul>
              </div>
            </div>
            <div className="rounded-2xl border border-line/70 p-4">
              <p className="text-[10px] font-extrabold tracking-wide text-muted uppercase">Official source field</p>
              <p className="mt-2 text-sm font-bold text-ink">{selected.sourceLabel}</p>
              <a href={selected.sourceUrl} target="_blank" rel="noreferrer" className="mt-3 inline-flex items-center gap-2 text-xs font-extrabold text-forest hover:underline">
                Open source <ArrowUpRight size={14} />
              </a>
            </div>
            <div className="flex justify-end"><Button variant="outline" onClick={() => setSelected(null)}>Close</Button></div>
          </div>
        ) : null}
      </Modal>
    </div>
  )
}

import { useMemo, useState } from 'react'
import { ArrowRight, ClipboardList } from 'lucide-react'
import { useNavigate } from 'react-router-dom'
import { PageHeader } from '../../components/common/PageHeader'
import { DemoNote } from '../../components/common/DemoNote'
import { FilterBar } from '../../components/common/FilterBar'
import { Card } from '../../components/ui/Card'
import { Badge, StatusPill } from '../../components/ui/Badge'
import { DataTable } from '../../components/ui/Table'
import type { Column } from '../../components/ui/Table'
import { useApp } from '../../services/store'
import { CROP_NAMES } from '../../data/crops'
import { formatDate } from '../../services/utils'
import type { CropCase } from '../../types'

export function AssignedCases() {
  const { cases } = useApp()
  const navigate = useNavigate()
  const [query, setQuery] = useState('')
  const [crop, setCrop] = useState('All crops')
  const [status, setStatus] = useState('All statuses')
  const [priority, setPriority] = useState('All priorities')

  const filtered = useMemo(() => {
    const q = query.trim().toLowerCase()
    return cases.filter((item) => {
      const matchesCrop = crop === 'All crops' || item.crop === crop
      const matchesStatus = status === 'All statuses' || item.reviewStatus === status.replace(' ', '_')
      const matchesPriority = priority === 'All priorities' || item.priority === priority.toLowerCase()
      const matchesQuery = !q || [item.id, item.farmerName, item.condition, item.location].some((value) => value.toLowerCase().includes(q))
      return matchesCrop && matchesStatus && matchesPriority && matchesQuery
    })
  }, [cases, query, crop, status, priority])

  const columns: Column<CropCase>[] = [
    { key: 'id', label: 'Case ID', render: (row) => <span className="font-extrabold text-ink">{row.id}</span> },
    { key: 'farmer', label: 'Farmer / location', render: (row) => <div><p className="font-bold text-ink">{row.farmerName}</p><p className="text-[11px] text-muted">{row.location}</p></div> },
    { key: 'crop', label: 'Crop', render: (row) => <Badge tone="sage">{row.crop}</Badge> },
    { key: 'condition', label: 'AI finding', render: (row) => row.condition },
    { key: 'priority', label: 'Priority', render: (row) => <StatusPill status={row.priority} /> },
    { key: 'review', label: 'Review', render: (row) => <StatusPill status={row.reviewStatus} /> },
    { key: 'date', label: 'Submitted', render: (row) => <span className="text-xs text-muted">{formatDate(row.submittedAt)}</span> },
    { key: 'action', label: 'Action', render: (row) => <button type="button" onClick={() => navigate(`/expert/case-details?id=${row.id}`)} className="inline-flex items-center gap-1 text-xs font-extrabold text-forest hover:underline">Open <ArrowRight size={13} /></button> },
  ]

  return (
    <div>
      <PageHeader
        eyebrow="Case workflow"
        title="Assigned Cases"
        description="Search and filter the demo case queue before opening a review."
        badge={<DemoNote label="Demo authorisation" />}
      />

      <FilterBar
        search={query}
        onSearch={setQuery}
        placeholder="Search case ID, farmer or finding…"
        selects={[
          { label: 'Crop', value: crop, onChange: setCrop, options: [{ value: 'All crops', label: 'All crops' }, ...CROP_NAMES.map((name) => ({ value: name, label: name }))] },
          { label: 'Status', value: status, onChange: setStatus, options: ['All statuses', 'pending', 'in review', 'completed', 'needs info'].map((name) => ({ value: name, label: name })) },
          { label: 'Priority', value: priority, onChange: setPriority, options: ['All priorities', 'High', 'Medium', 'Low'].map((name) => ({ value: name, label: name })) },
        ]}
        onReset={() => { setQuery(''); setCrop('All crops'); setStatus('All statuses'); setPriority('All priorities') }}
      >
        <span className="inline-flex items-center gap-2 text-xs font-bold text-muted"><ClipboardList size={14} /> {filtered.length} cases</span>
      </FilterBar>

      <Card>
        <DataTable
          columns={columns}
          rows={filtered}
          rowKey={(row) => row.id}
          onRowClick={(row) => navigate(`/expert/case-details?id=${row.id}`)}
          emptyMessage="No cases match the current filters."
        />
      </Card>
    </div>
  )
}

import { useMemo, useState } from 'react'
import type { ReactNode } from 'react'
import { Eye, ShieldAlert } from 'lucide-react'
import { PageHeader } from '../../components/common/PageHeader'
import { DemoNote } from '../../components/common/DemoNote'
import { FilterBar } from '../../components/common/FilterBar'
import { Card } from '../../components/ui/Card'
import { Button } from '../../components/ui/Button'
import { Modal } from '../../components/ui/Modal'
import { DataTable } from '../../components/ui/Table'
import type { Column } from '../../components/ui/Table'
import { StatCard } from '../../components/common/StatCard'
import { useApp } from '../../services/store'

export interface AdminFilter<T> {
  label: string
  options: string[]
  value: (row: T) => string
}

export interface AdminConfirm<T> {
  label: string
  description: (row: T) => string
  onConfirm: (row: T) => void
  danger?: boolean
}

interface AdminCollectionPageProps<T extends { id: string }> {
  eyebrow: string
  title: string
  description: string
  rows: T[]
  columns: Column<T>[]
  searchable: (row: T) => string[]
  searchPlaceholder?: string
  filters?: AdminFilter<T>[]
  stats?: { label: string; value: string | number; detail?: string; icon: ReactNode; tone?: 'sage' | 'forest' | 'alert' | 'neutral' }[]
  actions?: ReactNode
  detailTitle?: (row: T) => string
  detailDescription?: string
  detailContent?: (row: T) => ReactNode
  confirm?: AdminConfirm<T>
  emptyMessage?: string
}

export function AdminCollectionPage<T extends { id: string }>({
  eyebrow,
  title,
  description,
  rows,
  columns,
  searchable,
  searchPlaceholder = 'Search records…',
  filters = [],
  stats = [],
  actions,
  detailTitle,
  detailDescription = 'Demo record details.',
  detailContent,
  confirm,
  emptyMessage,
}: AdminCollectionPageProps<T>) {
  const { settings } = useApp()
  const [query, setQuery] = useState('')
  const [filterValues, setFilterValues] = useState<Record<string, string>>(() =>
    Object.fromEntries(filters.map((filter) => [filter.label, 'All'])),
  )
  const [detail, setDetail] = useState<T | null>(null)
  const [pendingConfirm, setPendingConfirm] = useState<T | null>(null)

  const visible = useMemo(() => {
    const q = query.trim().toLowerCase()
    return rows.filter((row) => {
      const matchesQuery = !q || searchable(row).some((value) => value.toLowerCase().includes(q))
      const matchesFilters = filters.every((filter) => {
        const selected = filterValues[filter.label] ?? 'All'
        return selected === 'All' || selected === filter.value(row)
      })
      return matchesQuery && matchesFilters
    })
  }, [rows, query, searchable, filters, filterValues])

  const tableColumns = useMemo<Column<T>[]>(() => {
    const actionColumn: Column<T> = {
      key: '_actions',
      label: 'Actions',
      render: (row) => (
        <div className="flex items-center gap-2">
          {detailContent ? (
            <Button
              type="button"
              size="sm"
              variant="outline"
              onClick={(event) => {
                event.stopPropagation()
                setDetail(row)
              }}
            >
              <Eye size={13} /> View
            </Button>
          ) : null}
          {confirm ? (
            <Button
              type="button"
              size="sm"
              variant={confirm.danger ? 'danger' : 'secondary'}
              onClick={(event) => {
                event.stopPropagation()
                setPendingConfirm(row)
              }}
            >
              {confirm.label}
            </Button>
          ) : null}
        </div>
      ),
    }
    return [...columns, actionColumn]
  }, [columns, detailContent, confirm])

  const reset = () => {
    setQuery('')
    setFilterValues(Object.fromEntries(filters.map((filter) => [filter.label, 'All'])))
  }

  return (
    <div>
      <PageHeader eyebrow={eyebrow} title={title} description={description} badge={<DemoNote label="Admin demo" />} actions={actions} />

      {stats.length > 0 ? (
        <div className="mb-6 grid gap-4 sm:grid-cols-2 xl:grid-cols-4">
          {stats.map((stat) => (
            <StatCard key={stat.label} label={stat.label} value={stat.value} detail={stat.detail} icon={stat.icon} tone={stat.tone ?? 'sage'} />
          ))}
        </div>
      ) : null}

      <FilterBar
        search={query}
        onSearch={setQuery}
        placeholder={searchPlaceholder}
        selects={filters.map((filter) => ({
          label: filter.label,
          value: filterValues[filter.label] ?? 'All',
          onChange: (value: string) => setFilterValues((current) => ({ ...current, [filter.label]: value })),
          options: [{ value: 'All', label: `All ${filter.label.toLowerCase()}` }, ...filter.options.map((option) => ({ value: option, label: option }))],
        }))}
        onReset={reset}
      >
        <span className="text-xs font-bold text-muted">{visible.length} of {rows.length} records shown</span>
      </FilterBar>

      <Card>
        <DataTable
          columns={tableColumns}
          rows={visible}
          rowKey={(row) => row.id}
          onRowClick={detailContent ? setDetail : undefined}
          compact={settings.compactTables}
          emptyMessage={emptyMessage ?? 'No records match the current filters.'}
        />
      </Card>

      <Modal
        open={detail !== null}
        onClose={() => setDetail(null)}
        title={detail && detailTitle ? detailTitle(detail) : 'Record details'}
        description={detailDescription}
        size="lg"
      >
        {detail && detailContent ? detailContent(detail) : null}
      </Modal>

      <Modal
        open={pendingConfirm !== null}
        onClose={() => setPendingConfirm(null)}
        title={confirm?.label ?? 'Confirm action'}
        description="This is a demo action. No external system is contacted."
        size="sm"
        footer={
          <>
            <Button variant="ghost" onClick={() => setPendingConfirm(null)}>Cancel</Button>
            <Button
              variant={confirm?.danger ? 'danger' : 'primary'}
              onClick={() => {
                if (pendingConfirm && confirm) confirm.onConfirm(pendingConfirm)
                setPendingConfirm(null)
              }}
            >
              <ShieldAlert size={15} /> Confirm
            </Button>
          </>
        }
      >
        {pendingConfirm && confirm ? <p className="text-sm leading-relaxed text-ink">{confirm.description(pendingConfirm)}</p> : null}
      </Modal>
    </div>
  )
}

import { ShieldCheck, Users } from 'lucide-react'
