import { useState } from 'react'
import { UserPlus } from 'lucide-react'
import { Button } from '../../components/ui/Button'
import { Field, Input } from '../../components/ui/Input'
import { Modal } from '../../components/ui/Modal'
import { useToast } from '../../context/ToastContext'
import { useApp } from '../../services/store'
import { makeId } from '../../services/utils'
import type { Role } from '../../types'

export function AdminAddUserModal({ role, open, onClose }: { role: Exclude<Role, 'admin'>; open: boolean; onClose: () => void }) {
  const { addUser, addAuditLog } = useApp()
  const { show } = useToast()
  const [name, setName] = useState('')
  const [email, setEmail] = useState('')
  const [location, setLocation] = useState('')
  const [phone, setPhone] = useState('')
  const [specialisation, setSpecialisation] = useState('')
  const [errors, setErrors] = useState<Record<string, string>>({})

  const reset = () => {
    setName('')
    setEmail('')
    setLocation('')
    setPhone('')
    setSpecialisation('')
    setErrors({})
    onClose()
  }

  const submit = () => {
    const next: Record<string, string> = {}
    if (name.trim().length < 3) next.name = 'Enter at least 3 characters.'
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email.trim())) next.email = 'Enter a valid email address.'
    if (location.trim().length < 2) next.location = 'Enter a location.'
    if (phone.trim().length < 7) next.phone = 'Enter a valid phone number.'
    if (role === 'expert' && specialisation.trim().length < 3) next.specialisation = 'Enter a specialisation.'
    setErrors(next)
    if (Object.keys(next).length > 0) return

    const initials = name.trim().split(/\s+/).slice(0, 2).map((part) => part[0]?.toUpperCase()).join('')
    addUser({
      id: makeId(role),
      name: name.trim(),
      email: email.trim(),
      role,
      location: location.trim(),
      phone: phone.trim(),
      status: 'invited',
      joinedAt: new Date().toISOString().slice(0, 10),
      avatar: initials || 'DU',
      specialisation: role === 'expert' ? specialisation.trim() : undefined,
      organisation: role === 'expert' ? 'KRISHI360 AI Demo' : undefined,
    })
    addAuditLog('Admin User', 'admin', 'Created demo account', `${role}: ${name.trim()}`)
    show('Demo account created', `${name.trim()} was added as ${role} with invited status.`)
    reset()
  }

  return (
    <Modal
      open={open}
      onClose={reset}
      title={`Add demo ${role}`}
      description="Creates a local demo record only. No invitation email is sent."
      footer={
        <>
          <Button variant="ghost" onClick={reset}>Cancel</Button>
          <Button onClick={submit}><UserPlus size={16} /> Add account</Button>
        </>
      }
    >
      <div className="grid gap-4 sm:grid-cols-2">
        <Field label="Full name" required error={errors.name}><Input value={name} onChange={(event) => setName(event.target.value)} placeholder="e.g. Ravi Patil" /></Field>
        <Field label="Email" required error={errors.email}><Input type="email" value={email} onChange={(event) => setEmail(event.target.value)} placeholder="name@example.com" /></Field>
        <Field label="Location" required error={errors.location}><Input value={location} onChange={(event) => setLocation(event.target.value)} placeholder="Nashik, Maharashtra" /></Field>
        <Field label="Phone" required error={errors.phone}><Input value={phone} onChange={(event) => setPhone(event.target.value)} placeholder="+91 98765 43210" /></Field>
        {role === 'expert' ? (
          <Field label="Specialisation" required error={errors.specialisation} className="sm:col-span-2"><Input value={specialisation} onChange={(event) => setSpecialisation(event.target.value)} placeholder="Plant pathology" /></Field>
        ) : null}
      </div>
    </Modal>
  )
}

import { useMemo, useState } from 'react'
import { Sprout, UserRoundCheck, Users } from 'lucide-react'
import { Button } from '../../components/ui/Button'
