import { Activity, CheckCircle2, Clock3, TriangleAlert } from 'lucide-react'
import { DemoNote } from '../../components/common/DemoNote'
import { StatusPill } from '../../components/ui/Badge'
import { formatDate } from '../../services/utils'
import { useApp } from '../../services/store'
import { AdminCollectionPage, type AdminFilter } from './AdminCollectionPage'
import type { Column } from '../../components/ui/Table'

type AdminCase = ReturnType<typeof useApp>['cases'][number]

const statusFilter: AdminFilter<AdminCase> = { label: 'Status', options: ['new', 'ai_review', 'expert_review', 'resolved'], value: (row) => row.status }
const priorityFilter: AdminFilter<AdminCase> = { label: 'Priority', options: ['high', 'medium', 'low'], value: (row) => row.priority }
const cropFilter: AdminFilter<AdminCase> = { label: 'Crop', options: ['Tomato', 'Wheat', 'Grapes', 'Onion', 'Rice', 'Cotton', 'Maize', 'Potato'], value: (row) => row.crop }

export function CropCaseManagementPage() {
  const { cases, reviewCase } = useApp()
  const columns: Column<AdminCase>[] = [
    { key: 'id', label: 'Case', render: (row) => <div><p className="font-bold text-ink">{row.id}</p><p className="text-xs text-muted">{formatDate(row.submittedAt)}</p></div> },
    { key: 'farmer', label: 'Farmer', render: (row) => <div><p className="font-semibold text-ink">{row.farmerName}</p><p className="text-xs text-muted">{row.location}</p></div> },
    { key: 'crop', label: 'Crop / issue', render: (row) => <div><p className="font-semibold text-ink">{row.crop}</p><p className="text-xs text-muted">{row.condition}</p></div> },
    { key: 'status', label: 'Status', render: (row) => <StatusPill status={row.status} /> },
    { key: 'priority', label: 'Priority', render: (row) => <StatusPill status={row.priority} /> },
  ]
  return (
    <AdminCollectionPage
      eyebrow="Operations"
      title="Crop case management"
      description="Monitor simulated diagnosis cases and expert-review states across the platform."
      rows={cases}
      columns={columns}
      searchable={(row) => [row.id, row.farmerName, row.crop, row.condition, row.location]}
      filters={[statusFilter, priorityFilter, cropFilter]}
      stats={[
        { label: 'Total cases', value: cases.length, detail: 'Submitted in demo', icon: <Activity size={18} />, tone: 'sage' },
        { label: 'Awaiting review', value: cases.filter((item) => item.status !== 'resolved').length, detail: 'Open or in review', icon: <Clock3 size={18} />, tone: 'forest' },
        { label: 'High priority', value: cases.filter((item) => item.priority === 'high').length, detail: 'Needs attention', icon: <TriangleAlert size={18} />, tone: 'alert' },
        { label: 'Resolved', value: cases.filter((item) => item.status === 'resolved').length, detail: 'Expert guidance shared', icon: <CheckCircle2 size={18} />, tone: 'neutral' },
      ]}
      detailTitle={(row) => `${row.id} · ${row.crop}`}
      detailContent={(row) => (
        <div className="space-y-5">
          <div className="grid gap-4 sm:grid-cols-2">
            <div><p className="text-xs font-bold uppercase tracking-wide text-muted">Farmer</p><p className="font-semibold text-ink">{row.farmerName}</p></div>
            <div><p className="text-xs font-bold uppercase tracking-wide text-muted">Location</p><p className="font-semibold text-ink">{row.location}</p></div>
            <div><p className="text-xs font-bold uppercase tracking-wide text-muted">Condition</p><p className="font-semibold text-ink">{row.condition}</p></div>
            <div><p className="text-xs font-bold uppercase tracking-wide text-muted">Status</p><StatusPill status={row.status} /></div>
          </div>
          <div><p className="text-xs font-bold uppercase tracking-wide text-muted">Symptoms</p><p className="mt-1 text-sm leading-relaxed text-ink">{row.symptoms}</p></div>
          <div><p className="text-xs font-bold uppercase tracking-wide text-muted">Explanation</p><p className="mt-1 text-sm leading-relaxed text-ink">{row.explanation}</p></div>
          <div>
            <p className="text-xs font-bold uppercase tracking-wide text-muted">Next steps</p>
            <ul className="mt-2 list-inside list-disc space-y-1 text-sm text-ink">{row.nextSteps.map((step) => <li key={step}>{step}</li>)}</ul>
          </div>
          <DemoNote label="Simulated diagnosis" />
        </div>
      )}
      confirm={{
        label: 'Toggle resolution',
        description: (row) => `${row.status === 'resolved' ? 'Reopen' : 'Mark resolved'} case ${row.id} in the local demo store? No farmer is notified.`,
        onConfirm: (row) =>
          reviewCase(
            row.id,
            row.expertNotes ?? 'Admin demo update.',
            row.expertGuidance ?? 'Continue monitoring and consult a local expert before applying any treatment.',
            row.status === 'resolved' ? 'pending' : 'completed',
            'Admin User',
          ),
      }}
    />
  )
}

import { useState } from 'react'
import { BellRing, Database, TrendingDown, TrendingUp } from 'lucide-react'
import { Button } from '../../components/ui/Button'
import { Badge } from '../../components/ui/Badge'
import { Field, Input } from '../../components/ui/Input'
import { Modal } from '../../components/ui/Modal'
import { DemoNote } from '../../components/common/DemoNote'
import { DEMO_MANDI_PRICES } from '../../data/mandiPrices'
import { useToast } from '../../context/ToastContext'
import { formatDate, formatINR } from '../../services/utils'
import { useApp } from '../../services/store'
import { AdminCollectionPage, type AdminFilter } from './AdminCollectionPage'
import type { Column } from '../../components/ui/Table'

type Price = (typeof DEMO_MANDI_PRICES)[number]

const cropFilter: AdminFilter<Price> = { label: 'Crop', options: [...new Set(DEMO_MANDI_PRICES.map((row) => row.crop))], value: (row) => row.crop }
const stateFilter: AdminFilter<Price> = { label: 'State', options: [...new Set(DEMO_MANDI_PRICES.map((row) => row.state))], value: (row) => row.state }

export function MandiDataManagementPage() {
  const { mandiAlerts, addMandiAlert, removeMandiAlert } = useApp()
  const { show } = useToast()
  const [alertsOpen, setAlertsOpen] = useState(false)
  const [crop, setCrop] = useState('Tomato')
  const [district, setDistrict] = useState('Nashik')
  const [target, setTarget] = useState('1900')
  const [error, setError] = useState('')

  const columns: Column<Price>[] = [
    { key: 'crop', label: 'Crop', render: (row) => <p className="font-bold text-ink">{row.crop}</p> },
    { key: 'mandi', label: 'Mandi', render: (row) => <div><p className="font-semibold text-ink">{row.mandi}</p><p className="text-xs text-muted">{row.district}, {row.state}</p></div> },
    { key: 'modal', label: 'Modal price', render: (row) => <p className="font-bold text-ink">{formatINR(row.modalPrice)}</p> },
    { key: 'range', label: 'Range', render: (row) => <p className="text-sm text-muted">{formatINR(row.minPrice)} – {formatINR(row.maxPrice)}</p> },
    {
      key: 'change',
      label: 'Change',
      render: (row) => (
        <Badge tone={row.changePct >= 0 ? 'success' : 'critical'} icon={row.changePct >= 0 ? <TrendingUp size={12} /> : <TrendingDown size={12} />}>
          {row.changePct >= 0 ? '+' : ''}{row.changePct}%
        </Badge>
      ),
    },
    { key: 'date', label: 'Date', render: (row) => formatDate(row.date) },
  ]

  const createAlert = (alertCrop: string, alertDistrict: string, alertTarget: string) => {
    const parsed = Number(alertTarget)
    if (alertCrop.trim().length < 2 || alertDistrict.trim().length < 2 || !Number.isFinite(parsed) || parsed <= 0) {
      setError('Enter a crop, district and a positive target price.')
      return false
    }
    addMandiAlert({ crop: alertCrop.trim(), district: alertDistrict.trim(), targetPrice: parsed })
    show('Price alert created', `${alertCrop.trim()} in ${alertDistrict.trim()} at ${formatINR(parsed)}.`)
    setError('')
    return true
  }

  return (
    <>
      <AdminCollectionPage
        eyebrow="Market data"
        title="Mandi data"
        description="Inspect the demonstration price dataset and manage local price alerts. These are not live market rates."
        rows={DEMO_MANDI_PRICES}
        columns={columns}
        searchable={(row) => [row.crop, row.mandi, row.district, row.state, row.source]}
        filters={[cropFilter, stateFilter]}
        stats={[
          { label: 'Price records', value: DEMO_MANDI_PRICES.length, detail: 'Static demo dataset', icon: <Database size={18} />, tone: 'sage' },
          { label: 'Crops tracked', value: new Set(DEMO_MANDI_PRICES.map((row) => row.crop)).size, detail: 'Across sample mandis', icon: <TrendingUp size={18} />, tone: 'forest' },
          { label: 'Price alerts', value: mandiAlerts.length, detail: 'Created in this session', icon: <BellRing size={18} />, tone: 'neutral' },
          { label: 'Data source', value: 'Demo', detail: 'No live feed connected', icon: <Database size={18} />, tone: 'alert' },
        ]}
        detailTitle={(row) => `${row.crop} · ${row.mandi}`}
        detailContent={(row) => (
          <div className="space-y-4">
            <div className="grid gap-4 sm:grid-cols-2">
              <div><p className="text-xs font-bold uppercase tracking-wide text-muted">Location</p><p className="font-semibold text-ink">{row.district}, {row.state}</p></div>
              <div><p className="text-xs font-bold uppercase tracking-wide text-muted">Record date</p><p className="font-semibold text-ink">{formatDate(row.date)}</p></div>
              <div><p className="text-xs font-bold uppercase tracking-wide text-muted">Minimum</p><p className="font-semibold text-ink">{formatINR(row.minPrice)}</p></div>
              <div><p className="text-xs font-bold uppercase tracking-wide text-muted">Maximum</p><p className="font-semibold text-ink">{formatINR(row.maxPrice)}</p></div>
              <div><p className="text-xs font-bold uppercase tracking-wide text-muted">Modal price</p><p className="font-semibold text-ink">{formatINR(row.modalPrice)}</p></div>
              <div><p className="text-xs font-bold uppercase tracking-wide text-muted">Change</p><p className="font-semibold text-ink">{row.changePct}%</p></div>
            </div>
            <DemoNote label="Simulated market data" />
            <p className="text-xs leading-relaxed text-muted">Source label: {row.source}. Do not use these values for selling decisions.</p>
          </div>
        )}
        confirm={{
          label: 'Create alert',
          description: (row) => `Create a demo price alert for ${row.crop} in ${row.district} at the modal price of ${formatINR(row.modalPrice)}?`,
          onConfirm: (row) => createAlert(row.crop, row.district, String(row.modalPrice)),
        }}
        actions={<Button size="sm" variant="outline" onClick={() => setAlertsOpen(true)}><BellRing size={14} /> Manage alerts ({mandiAlerts.length})</Button>}
      />

      <Modal
        open={alertsOpen}
        onClose={() => { setAlertsOpen(false); setError('') }}
        title="Price alerts"
        description="Create or remove demo-only price alerts. No notifications are sent externally."
        footer={<Button variant="ghost" onClick={() => setAlertsOpen(false)}>Close</Button>}
      >
        <div className="space-y-6">
          <div className="grid gap-4 sm:grid-cols-3">
            <Field label="Crop" required><Input value={crop} onChange={(event) => setCrop(event.target.value)} /></Field>
            <Field label="District" required><Input value={district} onChange={(event) => setDistrict(event.target.value)} /></Field>
            <Field label="Target (₹/quintal)" required error={error}><Input type="number" min="1" value={target} onChange={(event) => setTarget(event.target.value)} /></Field>
          </div>
          <Button onClick={() => createAlert(crop, district, target)}>Add alert</Button>
          <div className="space-y-2">
            {mandiAlerts.length === 0 ? (
              <p className="rounded-2xl border border-dashed border-line bg-white/50 px-4 py-6 text-center text-sm text-muted">No alerts created yet.</p>
            ) : mandiAlerts.map((alert) => (
              <div key={alert.id} className="flex flex-wrap items-center justify-between gap-3 rounded-2xl border border-line/80 bg-white/70 px-4 py-3">
                <div>
                  <p className="text-sm font-bold text-ink">{alert.crop} · {alert.district}</p>
                  <p className="text-xs text-muted">Target {formatINR(alert.targetPrice)} · {formatDate(alert.createdAt)}</p>
                </div>
                <Button size="sm" variant="ghost" onClick={() => { removeMandiAlert(alert.id); show('Alert removed', `${alert.crop} alert deleted from the demo.`) }}>Remove</Button>
              </div>
            ))}
          </div>
        </div>
      </Modal>
    </>
  )
}

import { useState } from 'react'
import { ClipboardCheck, Thermometer, Warehouse, Droplets } from 'lucide-react'
import { Button } from '../../components/ui/Button'
import { StatusPill } from '../../components/ui/Badge'
import { Field, Select, Textarea } from '../../components/ui/Input'
import { Modal } from '../../components/ui/Modal'
import { DemoNote } from '../../components/common/DemoNote'
import { formatDateTime, formatNumber } from '../../services/utils'
import { useToast } from '../../context/ToastContext'
import { useApp } from '../../services/store'
import { AdminCollectionPage, type AdminFilter } from './AdminCollectionPage'
import type { Column } from '../../components/ui/Table'

type Batch = ReturnType<typeof useApp>['storageBatches'][number]

const statusFilter: AdminFilter<Batch> = { label: 'Status', options: ['normal', 'warning', 'critical'], value: (row) => row.status }
const cropFilter: AdminFilter<Batch> = { label: 'Crop', options: ['Wheat', 'Rice', 'Onion', 'Potato', 'Tomato', 'Grapes'], value: (row) => row.crop }

export function StorageMonitoringPage() {
  const { storageBatches, settings, addInspection } = useApp()
  const { show } = useToast()
  const [inspectionOpen, setInspectionOpen] = useState(false)
  const [batchId, setBatchId] = useState('')
  const [notes, setNotes] = useState('')
  const [error, setError] = useState('')

  const columns: Column<Batch>[] = [
    { key: 'code', label: 'Batch', render: (row) => <div><p className="font-bold text-ink">{row.code}</p><p className="text-xs text-muted">{row.crop}</p></div> },
    { key: 'location', label: 'Location', render: (row) => row.location },
    { key: 'quantity', label: 'Quantity', render: (row) => `${formatNumber(row.quantityKg)} kg` },
    { key: 'temp', label: 'Temperature', render: (row) => <span className={row.tempC > settings.storageAlertTemp ? 'font-bold text-alert' : 'text-ink'}>{row.tempC}°C</span> },
    { key: 'humidity', label: 'Humidity', render: (row) => <span className={row.humidity > settings.storageAlertHumidity ? 'font-bold text-alert' : 'text-ink'}>{row.humidity}%</span> },
    { key: 'status', label: 'Status', render: (row) => <StatusPill status={row.status} /> },
  ]

  const submitInspection = () => {
    const selected = batchId || storageBatches[0]?.id
    if (!selected || notes.trim().length < 8) {
      setError('Select a batch and enter at least 8 characters of inspection notes.')
      return
    }
    addInspection(selected, notes.trim(), 'Admin User')
    show('Inspection recorded', 'The demo inspection entry was added to the batch history.')
    setNotes('')
    setError('')
    setInspectionOpen(false)
  }

  return (
    <>
      <AdminCollectionPage
        eyebrow="Storage network"
        title="Storage monitoring"
        description="Review sample storage batches, simulated sensor values and inspection histories."
        rows={storageBatches}
        columns={columns}
        searchable={(row) => [row.code, row.crop, row.location, row.status]}
        filters={[statusFilter, cropFilter]}
        stats={[
          { label: 'Batches', value: storageBatches.length, detail: 'Under demo observation', icon: <Warehouse size={18} />, tone: 'sage' },
          { label: 'Normal', value: storageBatches.filter((row) => row.status === 'normal').length, detail: 'Within sample thresholds', icon: <Warehouse size={18} />, tone: 'forest' },
          { label: 'Warnings', value: storageBatches.filter((row) => row.status === 'warning').length, detail: 'Needs attention', icon: <Thermometer size={18} />, tone: 'alert' },
          { label: 'Inspections', value: storageBatches.reduce((total, row) => total + row.inspections.length, 0), detail: 'Logged in demo', icon: <ClipboardCheck size={18} />, tone: 'neutral' },
        ]}
        detailTitle={(row) => `${row.code} · ${row.crop}`}
        detailContent={(row) => (
          <div className="space-y-5">
            <div className="grid gap-4 sm:grid-cols-2">
              <div><p className="text-xs font-bold uppercase tracking-wide text-muted">Location</p><p className="font-semibold text-ink">{row.location}</p></div>
              <div><p className="text-xs font-bold uppercase tracking-wide text-muted">Quantity</p><p className="font-semibold text-ink">{formatNumber(row.quantityKg)} kg</p></div>
              <div><p className="text-xs font-bold uppercase tracking-wide text-muted">Temperature</p><p className="font-semibold text-ink">{row.tempC}°C (limit {settings.storageAlertTemp}°C)</p></div>
              <div><p className="text-xs font-bold uppercase tracking-wide text-muted">Humidity</p><p className="font-semibold text-ink">{row.humidity}% (limit {settings.storageAlertHumidity}%)</p></div>
              <div><p className="text-xs font-bold uppercase tracking-wide text-muted">Safe range</p><p className="font-semibold text-ink">{row.minTemp}°C – {row.maxTemp}°C / ≤ {row.maxHumidity}%</p></div>
              <div><p className="text-xs font-bold uppercase tracking-wide text-muted">Status</p><StatusPill status={row.status} /></div>
            </div>
            <DemoNote label="Simulated sensor readings" />
            <div>
              <p className="text-xs font-bold uppercase tracking-wide text-muted">Inspection history</p>
              {row.inspections.length === 0 ? (
                <p className="mt-2 text-sm text-muted">No inspections recorded yet.</p>
              ) : (
                <div className="mt-2 space-y-2">
                  {row.inspections.map((inspection) => (
                    <div key={inspection.id} className="rounded-2xl border border-line/80 bg-white/70 px-4 py-3">
                      <p className="text-sm font-semibold text-ink">{inspection.notes}</p>
                      <p className="mt-1 text-xs text-muted">{inspection.inspector} · {formatDateTime(inspection.date)}</p>
                    </div>
                  ))}
                </div>
              )}
            </div>
          </div>
        )}
        confirm={{
          label: 'Quick check',
          description: (row) => `Add a standard demo inspection entry for batch ${row.code}?`,
          onConfirm: (row) => {
            addInspection(row.id, 'Routine demo inspection completed. Condition unchanged.', 'Admin User')
            show('Inspection recorded', `Standard check added to ${row.code}.`)
          },
        }}
        actions={<Button size="sm" variant="outline" onClick={() => { setBatchId(storageBatches[0]?.id ?? ''); setInspectionOpen(true) }}><ClipboardCheck size={14} /> Record inspection</Button>}
      />

      <Modal
        open={inspectionOpen}
        onClose={() => { setInspectionOpen(false); setError('') }}
        title="Record inspection"
        description="Add a local demo note to a storage batch."
        footer={<><Button variant="ghost" onClick={() => setInspectionOpen(false)}>Cancel</Button><Button onClick={submitInspection}>Save inspection</Button></>}
      >
        <div className="space-y-4">
          <Field label="Batch" required>
            <Select value={batchId} onChange={(event) => setBatchId(event.target.value)} options={storageBatches.map((batch) => ({ value: batch.id, label: `${batch.code} · ${batch.crop}` }))} />
          </Field>
          <Field label="Inspection notes" required error={error} hint="Describe the demo observation and any follow-up.">
            <Textarea value={notes} onChange={(event) => setNotes(event.target.value)} placeholder="Example: Ventilation checked; no visible spoilage." />
          </Field>
          <div className="flex items-center gap-2 rounded-2xl bg-soft-sage/60 px-4 py-3 text-xs font-semibold text-forest">
            <Droplets size={15} /> Sensor values in this portal are simulated for demonstration only.
          </div>
        </div>
      </Modal>
    </>
  )
}

import { ArrowUpRight, BellRing, FileText, Landmark } from 'lucide-react'
import { DemoNote } from '../../components/common/DemoNote'
import { Badge } from '../../components/ui/Badge'
import { useToast } from '../../context/ToastContext'
import { useApp } from '../../services/store'
import { AdminCollectionPage, type AdminFilter } from './AdminCollectionPage'
import type { Column } from '../../components/ui/Table'

type Scheme = ReturnType<typeof useApp>['schemes'][number]

const categoryFilter: AdminFilter<Scheme> = { label: 'Category', options: [...new Set(useAppSchemeCategories())], value: (row) => row.category }

function useAppSchemeCategories() {
  // Kept outside component render via a pure helper for the static demo catalogue.
  return ['Credit', 'Insurance', 'Irrigation', ' mechanisation', 'Export', 'Infrastructure', 'Digital', 'Organic', 'Development', 'Market', 'Sustainability', 'Storage', 'Women', 'Research']
}

export function SchemeManagementPage() {
  const { schemes, notify } = useApp()
  const { show } = useToast()
  const stateFilter: AdminFilter<Scheme> = { label: 'State', options: [...new Set(schemes.map((scheme) => scheme.state))], value: (row) => row.state }
  const filters: AdminFilter<Scheme>[] = [
    { label: 'Category', options: [...new Set(schemes.map((scheme) => scheme.category))], value: (row) => row.category },
    stateFilter,
  ]
  void categoryFilter

  const columns: Column<Scheme>[] = [
    { key: 'name', label: 'Scheme', render: (row) => <div><p className="font-bold text-ink">{row.name}</p><p className="text-xs text-muted">{row.category}</p></div> },
    { key: 'state', label: 'Coverage', render: (row) => row.state },
    { key: 'tags', label: 'Tags', render: (row) => <div className="flex flex-wrap gap-1">{row.tags.slice(0, 2).map((tag) => <Badge key={tag} tone="sage">{tag}</Badge>)}</div> },
    { key: 'source', label: 'Source', render: (row) => <a href={row.sourceUrl} target="_blank" rel="noreferrer" className="inline-flex items-center gap-1 text-xs font-bold text-forest underline">{row.sourceLabel} <ArrowUpRight size={12} /></a> },
  ]

  return (
    <AdminCollectionPage
      eyebrow="Scheme catalogue"
      title="Scheme management"
      description="Review the locally curated scheme catalogue and broadcast demo announcements to farmers."
      rows={schemes}
      columns={columns}
      searchable={(row) => [row.name, row.category, row.state, row.summary, ...row.tags]}
      filters={filters}
      stats={[
        { label: 'Schemes', value: schemes.length, detail: 'Curated demo entries', icon: <Landmark size={18} />, tone: 'sage' },
        { label: 'Categories', value: new Set(schemes.map((scheme) => scheme.category)).size, detail: 'Different support areas', icon: <FileText size={18} />, tone: 'forest' },
        { label: 'States', value: new Set(schemes.map((scheme) => scheme.state)).size, detail: 'Coverage labels', icon: <Landmark size={18} />, tone: 'neutral' },
        { label: 'Simulated', value: '100%', detail: 'No eligibility verification', icon: <FileText size={18} />, tone: 'alert' },
      ]}
      detailTitle={(row) => row.name}
      detailContent={(row) => (
        <div className="space-y-5">
          <div className="grid gap-4 sm:grid-cols-2">
            <div><p className="text-xs font-bold uppercase tracking-wide text-muted">Category</p><p className="font-semibold text-ink">{row.category}</p></div>
